update public.questions set question_text = $cm$Which statement is from the "Electric Fields and Capacitance" study notes?$cm$, options = to_jsonb(array[$cm$Exponential: V = V₀ e^(−t/RC). Time constant RC: after one RC, V falls to 37%. Half-life t½ = 0.69 RC$cm$::text, $cm$Angular speed ω = 2π/T; v = ωr; a = ω²r = v²/r; F = mv²/r toward the centre$cm$::text, $cm$Half-life: time for half the nuclei to decay. N = N₀ e^(−λt), λ = ln 2 / t½$cm$::text, $cm$Noise-cancelling headphones: destructive interference of antiphase sound$cm$::text]::text[]), correct_option = 0, explanation = $cm$From the Electric Fields and Capacitance study notes: “Exponential: V = V₀ e^(−t/RC). Time constant RC: after one RC, V falls to 37%. Half-life t½ = 0.69 RC”.$cm$ where id = '3ef5724e-9b07-45c8-98fd-9d5ddd8b8117';
