update public.past_papers p
set level = l.level,
    subject_slug = s.slug,
    updated_at = now()
from public.topics t
join public.subject_levels l on l.id = t.subject_level_id
join public.subjects s on s.id = l.subject_id
where p.topic_id = t.id
  and (p.level is distinct from l.level or p.subject_slug is distinct from s.slug);
update public.flashcards set front = $cm$Luminosity and Intensity$cm$, back = $cm$Luminosity L is total power radiated (W). Intensity at distance d: I = L/(4πd²) — the key to distances.$cm$, sort_order = 0 where id = 'f991ca77-90b6-441d-a0fc-549f2b15b115';
update public.flashcards set front = $cm$Wien and Stefan–Boltzmann$cm$, back = $cm$Wien: λ_max T = 2.9 × 10⁻³ m K — hotter stars are bluer$cm$, sort_order = 1 where id = '3e99db67-e814-41d3-bbe3-7c5ffef7df74';
update public.flashcards set front = $cm$Hubble's Law$cm$, back = $cm$Galaxies recede with v = Hd, H₀ ≈ 2.2 × 10⁻¹⁸ s⁻¹. Redshift z = Δλ/λ ≈ v/c for small z.$cm$, sort_order = 2 where id = 'e5e6187d-916b-4a34-a076-f50ed55fe772';
update public.flashcards set front = $cm$The Big Bang$cm$, back = $cm$Evidence: Hubble expansion, cosmic microwave background (2.7 K), hydrogen/helium abundance. Age estimate: t ≈ 1/H₀ ≈ 14 billion years. The fate question: critical density, Ω.$cm$, sort_order = 3 where id = '64aa53bb-bf45-4e32-8aa4-ad6ebed59ff0';
update public.flashcards set front = $cm$Standard candles$cm$, back = $cm$(Cepheid variables, Type Ia supernovae) have known L, so measuring I gives d.$cm$, sort_order = 4 where id = '04c498f8-a2cb-4578-a475-bf3e533f1f9c';
update public.flashcard_sets set description = $cm$Key terms and facts from the Astronomy and Cosmology study notes.$cm$ where id = '80486809-9b4a-4872-b410-9dd248bc7ff1';
update public.flashcards set front = $cm$Circular Motion Recap$cm$, back = $cm$Angular speed ω = 2π/T; v = ωr; a = ω²r = v²/r; F = mv²/r toward the centre.$cm$, sort_order = 0 where id = '2c31e229-d9e5-462e-bbe5-1c423ec8c77f';
update public.flashcards set front = $cm$Simple Harmonic Motion$cm$, back = $cm$Acceleration is proportional to displacement and opposite: a = −ω²x.$cm$, sort_order = 1 where id = '0507bf52-f678-4b5e-b216-d0f59b2b9769';
update public.flashcards set front = $cm$Energy in SHM$cm$, back = $cm$E = ½mω²x₀² total (constant), exchanged between KE (max at centre) and PE (max at extremes).$cm$, sort_order = 2 where id = '19f47914-4588-4ad7-863e-6446c963c291';
update public.flashcards set front = $cm$Damping and Resonance$cm$, back = $cm$Damping removes energy: light damping → slow decay; critical → fastest return without oscillation. Resonance: driving at the natural frequency gives maximum amplitude (microwave ovens, swing pushing, bridge disasters).$cm$, sort_order = 3 where id = '799aee38-055b-4d21-92c8-75d2315e1589';
update public.flashcard_sets set description = $cm$Key terms and facts from the Circular Motion and SHM study notes.$cm$ where id = 'b1b233a0-7284-4174-9c6d-2f2954f74428';
update public.flashcards set front = $cm$Coulomb's Law$cm$, back = $cm$F = q₁q₂/(4πε₀r²). Field strength E = F/q (N C⁻¹); for a point charge E = q/(4πε₀r²).$cm$, sort_order = 0 where id = '7b137c70-ed12-46d9-baec-be1532fb9b58';
update public.flashcards set front = $cm$Uniform Fields$cm$, back = $cm$Between parallel plates: E = V/d, constant.$cm$, sort_order = 1 where id = '38eb9190-9621-4c6a-bf6b-563ef7cd4b43';
update public.flashcards set front = $cm$Potential$cm$, back = $cm$V = W/q, scalar; E = −dV/dr. Potential energy of q at V is qV.$cm$, sort_order = 2 where id = '314139e7-9445-45be-bec0-9664eac0ef87';
update public.flashcards set front = $cm$Capacitance$cm$, back = $cm$C = Q/V (farads). Energy stored: W = ½QV = ½CV².$cm$, sort_order = 3 where id = 'c369d5d1-8fce-4782-a7cc-689aa950d6f5';
update public.flashcards set front = $cm$Charging and Discharging$cm$, back = $cm$Exponential: V = V₀ e^(−t/RC). Time constant RC: after one RC, V falls to 37%. Half-life t½ = 0.69 RC.$cm$, sort_order = 4 where id = '3d5d580a-8a62-465a-8b6b-46070b0a96d0';
update public.flashcards set front = $cm$Combinations$cm$, back = $cm$parallel adds (C = C₁ + C₂); series: 1/C = 1/C₁ + 1/C₂ (opposite to resistors).$cm$, sort_order = 5 where id = '281d07f0-aff0-4dfa-8064-dd860ef4c95e';
update public.flashcard_sets set description = $cm$Key terms and facts from the Electric Fields and Capacitance study notes.$cm$ where id = '19c43b32-4f72-44a4-8168-48157bd3e206';
update public.flashcards set front = $cm$Force on a Current$cm$, back = $cm$F = BIL sin θ (Fleming's left hand: field-index, current-first-finger, force-thumb).$cm$, sort_order = 0 where id = '6b3eeff1-803d-4236-926d-e948b2a52c31';
update public.flashcards set front = $cm$Force on a Moving Charge$cm$, back = $cm$F = BQv sin θ, always perpendicular to v → circular paths: r = mv/(BQ) (basis of cyclotrons and mass spectrometers).$cm$, sort_order = 1 where id = '5084ab34-0513-4fc5-8a00-a5f5cdf3c692';
update public.flashcards set front = $cm$Fields from Currents$cm$, back = $cm$Long straight wire: B = μ₀I/(2πr), circling by the right-hand grip rule$cm$, sort_order = 2 where id = '0bc628c9-1737-4ea5-a91b-fa60e7f939ac';
update public.flashcards set front = $cm$Electromagnetic Induction$cm$, back = $cm$Faraday: induced EMF = rate of flux cutting = N dΦ/dt. Lenz: induced effects oppose the change (negative sign).$cm$, sort_order = 3 where id = '2d857e18-ca48-4ca7-8ead-a0ff79232167';
update public.flashcard_sets set description = $cm$Key terms and facts from the Magnetic Fields and Electromagnetism study notes.$cm$ where id = 'f5cb3b33-586a-4deb-8b89-287ad8bb3fb4';
update public.flashcards set front = $cm$The Nucleus$cm$, back = $cm$Protons + neutrons (nucleons). Nuclide notation: ᴬZX — Z protons, A nucleons. Isotopes share Z, differ in N.$cm$, sort_order = 0 where id = '22aec09d-088b-4bcf-9408-0f532fbf0f20';
update public.flashcards set front = $cm$Radioactive Decay$cm$, back = $cm$Type What changes Stopped by$cm$, sort_order = 1 where id = 'c6ce66b5-4418-4ac4-9d71-274c71c655c6';
update public.flashcards set front = $cm$Mass–Energy$cm$, back = $cm$E = mc². Mass difference Δm in nuclear reactions becomes energy; binding energy = energy released assembling the nucleus. 1 u ≈ 931 MeV.$cm$, sort_order = 2 where id = 'e1a4bd7d-f428-430b-bcaf-6a2030e1e45a';
update public.flashcards set front = $cm$Fission and Fusion$cm$, back = $cm$Both release energy by moving toward iron (peak binding energy per nucleon): heavy nuclei split (fission, reactors), light nuclei merge (fusion, stars).$cm$, sort_order = 3 where id = '924a475e-a91f-47f3-b837-05d16e00ab7a';
update public.flashcards set front = $cm$Half-life$cm$, back = $cm$time for half the nuclei to decay. N = N₀ e^(−λt), λ = ln 2 / t½.$cm$, sort_order = 4 where id = '136f513c-c44d-4f49-b759-a87d02c4ea3f';
update public.flashcard_sets set description = $cm$Key terms and facts from the Nuclear Physics study notes.$cm$ where id = '625f005e-f2be-4fd0-87da-6088a5a4e25d';
update public.flashcards set front = $cm$Progressive vs Stationary$cm$, back = $cm$Progressive waves transfer energy; stationary waves store it in loops. Stationary patterns arise from two identical waves travelling in opposite directions (reflections on strings, air columns).$cm$, sort_order = 0 where id = 'b7fef6dd-7821-4eaa-b7e0-ddf70ebe65ef';
update public.flashcards set front = $cm$Harmonics$cm$, back = $cm$A string fixed at both ends: f₁ = v/2L, then 2f₁, 3f₁… Closed pipes resonate at odd multiples; open pipes at all multiples.$cm$, sort_order = 1 where id = 'ccde3745-3ea7-4494-86b1-086f90a94dcd';
update public.flashcards set front = $cm$Superposition Applications$cm$, back = $cm$Young's double slit: x = λD/a — evidence light is a wave$cm$, sort_order = 2 where id = '7ac35fbb-97ff-47b8-9cc8-49e63f0b3615';
update public.flashcards set front = $cm$Polarization Applications$cm$, back = $cm$Polaroid sunglasses cut glare from horizontal surfaces; stress analysis in plastics; LCD screens control light with twisted polarizers. Malus' law I = I₀cos²θ.$cm$, sort_order = 3 where id = 'd1c5e36c-b342-4213-bf8b-9de07700de53';
update public.flashcard_sets set description = $cm$Key terms and facts from the Oscillations and Waves II study notes.$cm$ where id = '65a3fb9e-eba1-4524-9302-e30cfb17e9be';
update public.flashcards set front = $cm$Photons$cm$, back = $cm$E = hf = hc/λ, h = 6.63 × 10⁻³⁴ J s.$cm$, sort_order = 0 where id = '3184aef8-4851-483f-a245-4a60297ce2a5';
update public.flashcards set front = $cm$The Photoelectric Effect$cm$, back = $cm$Light above a threshold frequency ejects electrons instantly; intensity alone does nothing below f₀.$cm$, sort_order = 1 where id = 'b6b679cf-e40e-4187-9112-6c6ca359b8c0';
update public.flashcards set front = $cm$Wave–Particle Duality$cm$, back = $cm$de Broglie: λ = h/p = h/(mv). Electrons diffract like waves — electron microscopes exploit short electron wavelengths.$cm$, sort_order = 2 where id = '901aa9e1-da4e-486c-ad79-2ec666295024';
update public.flashcards set front = $cm$Energy Levels and Line Spectra$cm$, back = $cm$Atoms absorb/emit photons matching level gaps: hf = E₁ − E₂. Emission lines are bright; absorption dark.$cm$, sort_order = 3 where id = '94c4bd17-05b3-49ac-8dd4-522840f16523';
update public.flashcard_sets set description = $cm$Key terms and facts from the Quantum Physics study notes.$cm$ where id = 'c477df2e-d7ac-46bd-852e-5af9a0a6be07';
update public.flashcards set front = $cm$Internal Energy$cm$, back = $cm$Sum of random kinetic + potential energies of molecules. Temperature rise → KE up; phase change → PE up (bonds stretch) at constant temperature.$cm$, sort_order = 0 where id = 'd379b022-7fe2-43bb-b0fb-e144301eb739';
update public.flashcards set front = $cm$Specific Heat and Latent Heat$cm$, back = $cm$Heating: Q = mcΔθ (c = specific heat capacity)$cm$, sort_order = 1 where id = 'bcca585d-3660-40b7-8c62-12ac5abb5d16';
update public.flashcards set front = $cm$Gas Laws$cm$, back = $cm$Boyle: pV = constant (T fixed)$cm$, sort_order = 2 where id = '7ffb2ca5-4c96-4fa3-aa57-63fb52cf1381';
update public.flashcards set front = $cm$Kinetic Theory$cm$, back = $cm$½m⟨c²⟩ = (3/2)kT — temperature measures mean translational KE. Also pV = ⅓Nm⟨c²⟩.$cm$, sort_order = 3 where id = 'a95dcfc9-29f3-4072-829b-3e98aaff3d40';
update public.flashcard_sets set description = $cm$Key terms and facts from the Thermal Physics study notes.$cm$ where id = '54511eff-803f-49a4-b183-77b3c2fdbb45';
update public.flashcards set front = $cm$Transmission$cm$, back = $cm$Serial : one bit at a time — cheaper, reliable over distance$cm$, sort_order = 0 where id = 'f8f5352a-a45b-49ff-86b1-341a1d99348a';
update public.flashcards set front = $cm$Packets and Protocols$cm$, back = $cm$Data splits into packets with header (addresses, sequence) and trailer (checksum). A protocol is an agreed rule set — without one, devices cannot interpret signals.$cm$, sort_order = 1 where id = 'ee9fa176-5a33-411c-b832-85844da402b2';
update public.flashcards set front = $cm$Network Types$cm$, back = $cm$LAN : small site, privately owned; WAN : large geographic scale (the internet)$cm$, sort_order = 2 where id = '307ff867-e6f9-47c6-9b9c-640c68ff9052';
update public.flashcards set front = $cm$Hardware$cm$, back = $cm$Routers join networks by IP; switches forward frames by MAC within a LAN; gateways translate protocols.$cm$, sort_order = 3 where id = '56556008-d2b1-42a8-b42a-bb1b8c13efbf';
update public.flashcards set front = $cm$Client-Server vs Peer-to-Peer$cm$, back = $cm$Client-server: central services, easy administration, single point of failure. P2P: every node shares files directly — cheap, hard to manage (torrents, blockchain).$cm$, sort_order = 4 where id = '1c407ba8-f53d-4327-ab96-fbfe46fb55ab';
update public.flashcards set front = $cm$Serial$cm$, back = $cm$one bit at a time — cheaper, reliable over distance$cm$, sort_order = 5 where id = '201fb0ad-f32b-43bb-8654-703ff8994317';
update public.flashcard_sets set description = $cm$Key terms and facts from the Communication and Networking study notes.$cm$ where id = 'd1a3f043-5a37-452c-b4f8-d82ff94607d2';
update public.flashcards set front = $cm$Arrays and Lists$cm$, back = $cm$Contiguous, indexed, O(1) access; fixed size. 2D arrays: element (i, j) — rows × columns.$cm$, sort_order = 0 where id = '55ed4101-ac58-48f2-8609-4beda392e80f';
update public.flashcards set front = $cm$Stack (LIFO)$cm$, back = $cm$push/pop/peek at one end. Uses: call stacks, undo, expression evaluation, DFS.$cm$, sort_order = 1 where id = '613abe8f-89a6-42f3-8389-c600a54466ee';
update public.flashcards set front = $cm$Queue (FIFO)$cm$, back = $cm$enqueue at rear, dequeue at front. Uses: print queues, schedulers, BFS. A circular queue reuses vacated slots with head/tail pointers modulo capacity.$cm$, sort_order = 2 where id = '83866441-8e80-4f94-aec1-783fdcfc40d0';
update public.flashcards set front = $cm$Linked List$cm$, back = $cm$Nodes with data + pointer. Insert/delete O(1) at a known node; search O(n). Traversal follows next pointers until null.$cm$, sort_order = 3 where id = '062b8381-09e4-4077-b1c8-7c4356413024';
update public.flashcards set front = $cm$Hash Table$cm$, back = $cm$Hash function maps keys → index. Collisions resolved by chaining or open addressing. Average O(1) lookup, worst O(n).$cm$, sort_order = 4 where id = '5672072e-a9c2-4815-88d3-dc270f869000';
update public.flashcards set front = $cm$Complexity$cm$, back = $cm$Operation Array Linked List Hash$cm$, sort_order = 5 where id = '0db46f25-abce-4f02-9f39-b66304ee6f81';
