update public.flashcards set front = $cm$Ethics of AI$cm$, back = $cm$Bias in training data → unfair outputs; opaque decisions → accountability gaps; job displacement; autonomous weapons.$cm$, sort_order = 4 where id = 'e6d17557-2f6b-44a5-bac9-de3d66b43ce3';
