update public.flashcards set front = $cm$Logic Gates$cm$, back = $cm$NOT inverts; NAND is 'AND then NOT'; XOR outputs 1 when inputs differ.$cm$, sort_order = 0 where id = '4819314b-7e21-4606-b342-934fa369f765';
update public.flashcards set front = $cm$Boolean Algebra Laws$cm$, back = $cm$De Morgan: (A·B)′ = A′ + B′; (A + B)′ = A′ · B′$cm$, sort_order = 1 where id = '01de10f6-d479-47e9-9060-4b91d94a0828';
update public.flashcards set front = $cm$Constructing Circuits$cm$, back = $cm$Truth table → Boolean expression → gates. A half adder: S = A XOR B, C = A AND B.$cm$, sort_order = 2 where id = '38635b97-7d33-44fa-8dcc-673d163bdb80';
update public.flashcards set front = $cm$Flip-Flops (Bistables)$cm$, back = $cm$SR latch : set/reset, invalid state S=R=1$cm$, sort_order = 3 where id = 'fdcec10e-3f0b-4e70-acee-1d643c40b0a3';
update public.flashcards set front = $cm$Von Neumann Model$cm$, back = $cm$CPU (ALU, control unit, registers: PC, MAR, MDR, ACC) + memory + I/O, sharing one bus system; instructions fetched–decoded–executed in cycles.$cm$, sort_order = 4 where id = '03ef6e9a-c368-430d-a266-05f65026d918';
update public.flashcard_sets set description = $cm$Key terms and facts from the Hardware and Logic Gates study notes.$cm$ where id = '6da7364a-3c81-4086-8889-aad04e614628';
update public.flashcards set front = $cm$Number Systems and Ranges$cm$, back = $cm$Unsigned binary with n bits stores 0 to 2ⁿ − 1. Two's complement represents negatives: the MSB has value −2ⁿ⁻¹.$cm$, sort_order = 0 where id = '64757a07-d6f9-42e3-ad2c-000e1d66748f';
update public.flashcards set front = $cm$Binary Arithmetic$cm$, back = $cm$Add: 0+0=0, 0+1=1, 1+1=0 carry 1, 1+1+1=1 carry 1. Overflow happens when a result exceeds the word size.$cm$, sort_order = 1 where id = '3b4bc7d3-c350-4513-8a56-e825ed5a8f10';
update public.flashcards set front = $cm$Text$cm$, back = $cm$ASCII : 7 bits, 128 characters, English only$cm$, sort_order = 2 where id = 'e5933df6-43ff-456c-810e-fb55c65bca9e';
update public.flashcards set front = $cm$Images and Sound$cm$, back = $cm$Bitmap: pixels with colour depth (bits per pixel). File size = width × height × depth.$cm$, sort_order = 3 where id = '8b8f2dc2-d77b-46e0-a978-5bd92eb13aec';
update public.flashcards set front = $cm$Compression$cm$, back = $cm$Lossless (ZIP, run-length encoding): exact reconstruction — required for text/code$cm$, sort_order = 4 where id = 'c3a5fe0a-3879-4523-81a6-bae18942d7a2';
update public.flashcards set front = $cm$ASCII$cm$, back = $cm$7 bits, 128 characters, English only$cm$, sort_order = 5 where id = 'caa41284-8ba9-4d50-8b2a-6eb4236313eb';
update public.flashcard_sets set description = $cm$Key terms and facts from the Information Representation study notes.$cm$ where id = 'ab37859a-d1bc-4552-b7ed-d9204226616c';
update public.flashcards set front = $cm$The FDE Cycle$cm$, back = $cm$Fetch : PC → MAR; read memory → MDR; instruction → CIR; PC increments$cm$, sort_order = 0 where id = '0b550003-a276-4c98-b04e-cf6f26334660';
update public.flashcards set front = $cm$Registers$cm$, back = $cm$PC address of next instruction$cm$, sort_order = 1 where id = '11fb7db9-18ed-497e-b555-f325804429bb';
update public.flashcards set front = $cm$Buses$cm$, back = $cm$Address bus : one-way, CPU → memory (width sets addressable space)$cm$, sort_order = 2 where id = 'fc88db35-d377-4663-8a99-824cab4fe572';
update public.flashcards set front = $cm$Interrupts$cm$, back = $cm$Signals that pause the current program (I/O complete, timer, errors). The CPU saves context, runs the ISR, then resumes — enabling multitasking.$cm$, sort_order = 3 where id = '479ba2fd-9ca9-49b5-b358-242a1782fbf5';
update public.flashcards set front = $cm$Assembly and Addressing$cm$, back = $cm$Immediate (#5), direct (address holds value), indirect (address points to address), indexed (base + offset — arrays), relative (PC + offset — jumps).$cm$, sort_order = 4 where id = '27e9d662-8b98-4ca8-b9cb-243984d0ea1b';
update public.flashcards set front = $cm$Fetch$cm$, back = $cm$PC → MAR; read memory → MDR; instruction → CIR; PC increments$cm$, sort_order = 5 where id = '8f071a03-0b2d-4d1d-b0ba-463a4ce03526';
update public.flashcard_sets set description = $cm$Key terms and facts from the Processor Fundamentals study notes.$cm$ where id = '6274a521-9e18-434e-9783-481490c41737';
update public.flashcards set front = $cm$Design Approaches$cm$, back = $cm$Top-down (stepwise refinement) : decompose into modules — planned structure$cm$, sort_order = 0 where id = '9d74fd34-ab27-4474-a435-39ed0726803b';
update public.flashcards set front = $cm$Pseudocode Conventions$cm$, back = $cm$IF x > 10 THEN ... ELSE ... ENDIF$cm$, sort_order = 1 where id = '05b79eeb-d37e-4d59-b6d3-562020b90bcb';
update public.flashcards set front = $cm$Searching$cm$, back = $cm$Linear : check each item, O(n), works unsorted$cm$, sort_order = 2 where id = '6c32a7d2-7d9f-4358-ad56-b7344efb891f';
update public.flashcards set front = $cm$Sorting$cm$, back = $cm$Algorithm Best Average Idea$cm$, sort_order = 3 where id = '155a7eab-0215-448f-ba8b-86efd32c05d4';
update public.flashcards set front = $cm$Recursion$cm$, back = $cm$A function calling itself with a base case. Factorial: f(0)=1, f(n)=n·f(n−1). Stack frames handle state.$cm$, sort_order = 4 where id = '2c5eb63d-0f22-415f-a835-9df394aa7584';
update public.flashcards set front = $cm$Top-down (stepwise refinement)$cm$, back = $cm$decompose into modules — planned structure$cm$, sort_order = 5 where id = '309f341a-f0d6-486b-b61c-a42ee926f982';
update public.flashcard_sets set description = $cm$Key terms and facts from the Programming and Algorithms study notes.$cm$ where id = '658dc798-ba46-4929-903f-7aad5463e9f5';
update public.flashcards set front = $cm$Operating System Roles$cm$, back = $cm$Manage memory (paging/segmentation, virtual memory to disk)$cm$, sort_order = 0 where id = '008188d4-a34e-42ba-9971-73cdf8f1f048';
update public.flashcards set front = $cm$Translators$cm$, back = $cm$Assembler : assembly → machine code (1:1)$cm$, sort_order = 1 where id = 'db3332dd-c64f-41cc-bfbc-d2b164b1fb0e';
update public.flashcards set front = $cm$Linkers and Loaders$cm$, back = $cm$Static linking copies library code into the executable; dynamic linking binds at runtime (smaller files, shared libraries). The loader places the program in memory, relocating addresses.$cm$, sort_order = 2 where id = '367e4e2c-37e6-44ba-a591-6ee28eac185d';
update public.flashcards set front = $cm$IDEs$cm$, back = $cm$Editors with syntax highlighting, autocompletion, debugger (breakpoints, stepping, variable watch), and integrated compilation.$cm$, sort_order = 3 where id = '7f664851-214c-4b35-be15-1437f575a68e';
update public.flashcards set front = $cm$Malware and Defences$cm$, back = $cm$Viruses, worms, trojans, spyware, phishing. Defences: antivirus (signature + heuristic scanning), firewalls (packet filtering by port/IP), sandboxing, user education, patches.$cm$, sort_order = 4 where id = '3d610af6-a3b0-4974-b8ed-adff7d43cf50';
update public.flashcards set front = $cm$Assembler$cm$, back = $cm$assembly → machine code (1:1)$cm$, sort_order = 5 where id = 'c8cb6922-9086-49a2-9d3b-6150df88fdc7';
update public.flashcard_sets set description = $cm$Key terms and facts from the System Software and Security study notes.$cm$ where id = 'a7cabf3b-9c20-4caa-830f-a1f06ee600c4';
update public.flashcards set front = $cm$Thinking Ahead, Abstractly, Systematically$cm$, back = $cm$Abstraction : keep essential features, drop detail — a metro map ignores street geometry.$cm$, sort_order = 0 where id = 'cbb9e703-2dc0-485d-af43-90834f98b314';
update public.flashcards set front = $cm$Recursion$cm$, back = $cm$A recursive routine calls itself with a smaller input and a base case that stops the recursion. Elegant for trees and divide-and-conquer, but each call consumes stack space — deep recursion can overflow.$cm$, sort_order = 1 where id = '243fb161-265b-4dd4-84f8-5d78790ee4a8';
update public.flashcards set front = $cm$Searching and Sorting$cm$, back = $cm$Linear search : O(n), works unsorted.$cm$, sort_order = 2 where id = '94ce9ded-2724-450b-bf41-66a68f4a1938';
update public.flashcards set front = $cm$Testing$cm$, back = $cm$White-box tests trace internal paths; black-box tests check specification behaviour. Choose normal, boundary and erroneous data. Dry runs use trace tables recording variables line by line; a trace of recursion should log each call and its return.$cm$, sort_order = 3 where id = '63db1bd8-45cd-4e97-8bdf-43ea3d8d0d98';
update public.flashcards set front = $cm$Thinking ahead$cm$, back = $cm$pre-plan inputs, outputs and reusable components; pre-calculate tables where possible.$cm$, sort_order = 4 where id = 'fe442ed0-7662-43e9-8f9f-f5598a45033e';
update public.flashcards set front = $cm$base case$cm$, back = $cm$that stops the recursion. Elegant for trees and divide-and-conquer, but each call consumes stack space — deep recursion can overflow. Any recursion can be rewritten with a loop and explicit stack.$cm$, sort_order = 5 where id = 'ffcf18b9-332c-4933-83b5-c64a1e63b788';
update public.flashcard_sets set description = $cm$Key terms and facts from the Computational Thinking and Problem-Solving study notes.$cm$ where id = 'c115ca1d-68eb-42df-b051-3dccc761a1d5';
update public.flashcards set front = $cm$The TCP/IP Stack$cm$, back = $cm$Four layers: Application (HTTP, FTP, SMTP, DNS), Transport (TCP reliable, connection-oriented with sequence numbers and acknowledgements; UDP fast, connectionless), Internet (IP addressing and routing), Link (physical delivery on the local network).$cm$, sort_order = 0 where id = '3f9f1c9d-8401-403f-b0e4-1a2efbbb5369';
update public.flashcards set front = $cm$Switching$cm$, back = $cm$Circuit switching : a dedicated path is held for the call (traditional telephone) — wasteful if idle.$cm$, sort_order = 1 where id = 'eaa54c89-4798-41a4-9174-b4f0a732459a';
update public.flashcards set front = $cm$Addressing and Subnetting$cm$, back = $cm$IPv4 addresses are 32 bits, written dotted decimal, split into network + host portions by the subnet mask. ANDing an IP with the mask yields the network ID. 192.168.4.0/26 means the first 26 bits are network, leaving 6 host bits: 64 addresses, 62 usable.$cm$, sort_order = 2 where id = 'c0c9af6a-9e57-4cbf-8681-a72e9ecbd765';
update public.flashcards set front = $cm$Models and Protection$cm$, back = $cm$Client-server centralises services (web, email, files); peer-to-peer shares directly (torrents, small LANs). Firewalls filter traffic by rules; proxy servers sit between clients and the internet, caching and filtering;$cm$, sort_order = 3 where id = '97d728d4-fc48-4f5d-a3a2-48f9fe07e0fc';
update public.flashcards set front = $cm$Transport$cm$, back = $cm$(TCP reliable, connection-oriented with sequence numbers and acknowledgements; UDP fast, connectionless),$cm$, sort_order = 4 where id = 'f38595b8-53c2-447e-8c66-8ce65ec186c8';
update public.flashcards set front = $cm$Internet$cm$, back = $cm$(IP addressing and routing),$cm$, sort_order = 5 where id = 'dc60541c-94dc-4765-ae82-b4512ab9de90';
update public.flashcard_sets set description = $cm$Key terms and facts from the Networks and the Internet study notes.$cm$ where id = '0649e869-6bcb-4247-a462-a6228d37357b';
update public.flashcards set front = $cm$The Three Layers$cm$, back = $cm$HTML gives structure and content: elements, attributes, forms for user input.$cm$, sort_order = 0 where id = 'fad04c24-906b-4b1b-9ccc-bafeb46d811b';
update public.flashcards set front = $cm$SQL Injection$cm$, back = $cm$An attack where crafted input changes the meaning of a query. If a login query concatenates the username directly, entering X OR 1=1 can match every row. Defences: parameterised queries (prepared statements)$cm$, sort_order = 1 where id = '5ddba5cd-69d2-444d-baf1-b1a403a140db';
update public.flashcards set front = $cm$Encryption$cm$, back = $cm$Symmetric : one shared key (AES). Fast, but key distribution is the weak point.$cm$, sort_order = 2 where id = 'bf5adcbe-cc73-4769-9c3b-05423bb5e8f0';
update public.flashcards set front = $cm$Hashing vs Encryption$cm$, back = $cm$Hashing (e.g. SHA-256) is one-way: passwords should be stored hashed with a unique salt, never encrypted reversibly.$cm$, sort_order = 3 where id = 'b99f0acb-70f6-43ab-bb13-93531b56622d';
update public.flashcards set front = $cm$HTML$cm$, back = $cm$gives structure and content: elements, attributes, forms for user input.$cm$, sort_order = 4 where id = '4f23aa92-50a7-4779-9846-fe08866842d0';
update public.flashcards set front = $cm$CSS$cm$, back = $cm$gives presentation: selectors, properties, responsive layout.$cm$, sort_order = 5 where id = 'fc3bc6dd-9ae9-4772-98e2-4392fd8561f9';
update public.flashcard_sets set description = $cm$Key terms and facts from the Web Technologies and Security study notes.$cm$ where id = '4a11ccc3-5da7-46df-a620-fe2f3d361b36';
update public.flashcards set front = $cm$When Binomial Applies$cm$, back = $cm$X ~ B(n, p) counts successes in n independent trials when:$cm$, sort_order = 0 where id = '3dcdd394-da21-4ea5-b5fe-842b417e0951';
update public.flashcards set front = $cm$The Formula$cm$, back = $cm$P(X = r) = ⁿCᵣ pʳ(1 − p)ⁿ⁻ʳ for r = 0, 1, ..., n. The ⁿCᵣ counts which r of the n trials were the successes.$cm$, sort_order = 1 where id = '0b207a1a-e329-4049-9973-4619995495c0';
update public.flashcards set front = $cm$Cumulative Probabilities$cm$, back = $cm$P(X ≤ 2) = P(0) + P(1) + P(2). "At least" questions convert by the complement: P(X ≥ 2) = 1 − P(X ≤ 1). Keep one extra decimal place in intermediate steps to avoid rounding drift.$cm$, sort_order = 2 where id = '2f47698f-6614-4a49-a8a6-106752c12666';
update public.flashcards set front = $cm$Expectation and Variance$cm$, back = $cm$E(X) = np and Var(X) = np(1 − p)$cm$, sort_order = 3 where id = '94e8b8bb-2d38-4e9f-8890-3c480768b677';
update public.flashcards set front = $cm$Modelling Decisions$cm$, back = $cm$If trials are dependent (drawing without replacement from a small population) binomial is not appropriate. If p changes between trials it is not binomial. When n is large and p small, the binomial is approximately Poisson — but at A2 you usually stay exact.$cm$, sort_order = 4 where id = '32f30a2c-5275-4302-aaec-7f68fae2eb88';
update public.flashcard_sets set description = $cm$Key terms and facts from the Binomial Distribution study notes.$cm$ where id = '885e0e9a-0edb-4245-a57b-47b8be60c1b6';
update public.flashcards set front = $cm$Probability Density Functions$cm$, back = $cm$A continuous variable X is described by a density f(x) with f(x) ≥ 0 and ∫f(x)dx = 1 over all x. Probabilities are areas:$cm$, sort_order = 0 where id = '36ee0f09-9c6f-4b14-b179-07c0bb347937';
update public.flashcards set front = $cm$Finding Unknown Constants$cm$, back = $cm$Piecewise densities carry an unknown k: impose that the total area is 1 (and continuity at joins where required). One equation, one unknown.$cm$, sort_order = 1 where id = 'ba5bc032-0ba7-4b55-a77c-f20dd86759e3';
update public.flashcards set front = $cm$Expectation and Variance$cm$, back = $cm$The mean is the balancing point of the area under the density. For symmetric densities the mean sits at the symmetry point — worth spotting before integrating.$cm$, sort_order = 2 where id = '20a0f8f3-8212-4614-896d-9126454e8676';
update public.flashcards set front = $cm$The Median and Mode$cm$, back = $cm$The median m solves ∫₋∞ᵐ f(x) dx = 0.5 (left half of the area). The mode is the x maximising f(x). For uniform densities the median is the midpoint.$cm$, sort_order = 3 where id = '497c1224-c79a-494f-bc7b-b75284d3b010';
update public.flashcards set front = $cm$Uniform Distribution$cm$, back = $cm$If f(x) = 1/(b − a) on [a, b], every point is equally likely. Then E(X) = (a + b)/2 and Var(X) = (b − a)��/12 — memorise both; they are quick exam marks.$cm$, sort_order = 4 where id = '6b81f55e-64ca-4b8f-83c6-244df811412b';
update public.flashcard_sets set description = $cm$Key terms and facts from the Continuous Random Variables study notes.$cm$ where id = '7d3ca0b8-2428-4f24-8f0f-6d0845f3d9f6';
update public.flashcards set front = $cm$The Framework$cm$, back = $cm$The null hypothesis H₀ is the default claim (no change, p = p₀). The alternative H₁ is what a suspicious observation suggests (p > p₀, p < p₀, or p ≠ p₀).$cm$, sort_order = 0 where id = '77276539-475b-4219-af14-e69f14219246';
update public.flashcards set front = $cm$Test for a Binomial Proportion$cm$, back = $cm$With X ~ B(n, p₀) under H₀, compute the probability of results at least as extreme as the observed count in the direction of H₁.$cm$, sort_order = 1 where id = 'bf253165-be72-4d34-bf52-4915f1ba4d5b';
update public.flashcards set front = $cm$One-Tailed vs Two-Tailed$cm$, back = $cm$One-tailed tests take the whole α in one direction. Two-tailed tests split α across both tails: compare against α/2 on each side, or equivalently check whether the observation falls in the extreme 2.5% (for α = 5%).$cm$, sort_order = 2 where id = '5a20a42e-4c97-4ddb-a8f3-2b6abbb94fe3';
insert into public.flashcards (set_id, front, back, sort_order) values ('bb3238c1-81b4-4781-8a78-d32a39be7103', $cm$Critical Regions$cm$, $cm$The critical region is the set of values of the test statistic that would lead to rejection. Its boundary is the critical value. For B(20, 0.3) at the 5% level with H₁: p > 0.3, find the smallest k with P(X ≥ k) < 0.05 — that k opens the critical region.$cm$, 3);
insert into public.flashcards (set_id, front, back, sort_order) values ('bb3238c1-81b4-4781-8a78-d32a39be7103', $cm$Conclusions in Context$cm$, $cm$Never just say "reject H₀". Conclude in the language of the problem: "there is sufficient evidence at the 5% level that the proportion has increased". State the significance level, the direction, and the real-world quantity.$cm$, 4);
update public.flashcard_sets set description = $cm$Key terms and facts from the Hypothesis Testing study notes.$cm$ where id = 'bb3238c1-81b4-4781-8a78-d32a39be7103';
update public.flashcards set front = $cm$Range and Quartiles$cm$, back = $cm$The range is max − min — quick but destroyed by a single outlier. Quartiles split ordered data into quarters: Q₁ at position (n + 1)/4, Q₃ at 3(n + 1)/4 (raw data). The interquartile range, IQR = Q₃ − Q₁, is the spread of the middle 50% and resists outliers.$cm$, sort_order = 0 where id = '866ff098-1536-4fff-86e3-6689cf81a3b9';
update public.flashcards set front = $cm$Variance and Standard Deviation$cm$, back = $cm$variance s² = Σ(x − x̄)²/n (the definitional form)$cm$, sort_order = 1 where id = '0d0efd63-7758-4b6d-9e91-e525e8a4d1a3';
update public.flashcards set front = $cm$Grouped Data$cm$, back = $cm$Use class midpoints as x. The result is an estimate — grouping discards within-class detail.$cm$, sort_order = 2 where id = 'fef1465a-d56f-4fba-8d39-2db7fb24c211';
insert into public.flashcards (set_id, front, back, sort_order) values ('656f3c57-d858-48b2-898e-ce99343a124c', $cm$Combining and Scaling Datasets$cm$, $cm$Multiplying every value by b multiplies s by |b| and the variance by b². Adding a constant changes nothing in the spread. Two merged datasets: compute combined Σx and Σx² from each part, then apply the computational formula.$cm$, 3);
update public.flashcard_sets set description = $cm$Key terms and facts from the Measures of Variation and Standard Deviation study notes.$cm$ where id = '656f3c57-d858-48b2-898e-ce99343a124c';
update public.flashcards set front = $cm$The Mean$cm$, back = $cm$For data x₁, ..., xₙ the mean is$cm$, sort_order = 0 where id = 'b303423d-b874-444b-9d1d-9a7701b21f20';
update public.flashcards set front = $cm$The Median$cm$, back = $cm$The median is the middle value: position (n + 1)/2 for ordered raw data. With n even, average the two middle values. The median ignores the size of extreme values, so it describes skewed data more honestly.$cm$, sort_order = 1 where id = '9d56c616-63f1-4469-8592-f0ac68131181';
update public.flashcards set front = $cm$The Mode$cm$, back = $cm$The most frequent value. A dataset may have no mode or several. For grouped data the modal class is the one with the highest frequency density (frequency ÷ class width), not the highest frequency.$cm$, sort_order = 2 where id = 'be6704ff-9fcd-4e55-9a13-54eb854918bd';
update public.flashcards set front = $cm$Effects of Data Changes$cm$, back = $cm$Adding a constant a to every value adds a to the mean and median (the mode too) but leaves the spread untouched. Multiplying every value by b multiplies mean and median by b.$cm$, sort_order = 3 where id = '6ce0523e-6ba7-4d3d-afd6-1f09062747b7';
insert into public.flashcards (set_id, front, back, sort_order) values ('385118c3-a705-4b80-8097-68ae529acc08', $cm$Coding$cm$, $cm$Subtract a constant and divide by a convenient width: y = (x − a)/b. Then x̄ = b·ȳ + a. Coding simplifies arithmetic and always preserves the relationship — the coded mean decodes exactly.$cm$, 4);
update public.flashcard_sets set description = $cm$Key terms and facts from the Numerical Measures of Central Tendency study notes.$cm$ where id = '385118c3-a705-4b80-8097-68ae529acc08';
update public.flashcards set front = $cm$Radians$cm$, back = $cm$One radian is the angle subtending an arc equal in length to the radius. π radians = 180°.$cm$, sort_order = 0 where id = '0a26004e-c4a3-42b4-9033-146d0ce13633';
update public.flashcards set front = $cm$Arc Length$cm$, back = $cm$Example: r = 6, θ = π/3 gives s = 2π.$cm$, sort_order = 1 where id = '0c4a1a99-d62f-4f38-a25b-98f663dfff95';
update public.flashcards set front = $cm$Sector Area$cm$, back = $cm$Example: r = 5, θ = 1.2 gives A = ½ × 25 × 1.2 = 15.$cm$, sort_order = 2 where id = '55b113d8-3eba-437b-907d-8ad6279b7532';
update public.flashcards set front = $cm$Segment Area$cm$, back = $cm$A = ½r²(θ − sin θ). For r = 2, θ = π/2: A = 2(π/2 − 1) = π − 2.$cm$, sort_order = 3 where id = '5bc4879b-4fb0-4130-8d2e-835d051c00d2';
update public.flashcards set front = $cm$Rearranging$cm$, back = $cm$Exam tips: never mix degrees into s = rθ; convert first. Sketch the sector and mark r and θ before computing, and check whether a question asks for the major or minor sector.$cm$, sort_order = 4 where id = '134535c5-5993-4148-8360-393a79288f0a';
update public.flashcard_sets set description = $cm$Key terms and facts from the Circular Measure study notes.$cm$ where id = '23b93670-44a3-4aba-abf0-a9da7ef1a444';
update public.flashcards set front = $cm$Gradients and Equations of Lines$cm$, back = $cm$Gradient m = (y₂ − y₁)/(x₂ − x₁). From ax + by + c = 0, the gradient is −a/b.$cm$, sort_order = 0 where id = '51f455bb-0482-419e-972e-9218f5525ee1';
update public.flashcards set front = $cm$Parallel and Perpendicular$cm$, back = $cm$Parallel lines: equal gradients.$cm$, sort_order = 1 where id = 'd3a5bf67-a2a4-42d8-997c-82b00084496b';
update public.flashcards set front = $cm$Midpoint and Distance$cm$, back = $cm$Midpoint of (x₁, y₁), (x₂, y₂): ((x₁+x₂)/2, (y₁+y₂)/2).$cm$, sort_order = 2 where id = '5574dfed-ae3a-4df2-867e-f8b39f2927c7';
update public.flashcards set front = $cm$Intersections and Bisectors$cm$, back = $cm$Intersections: solve the equations simultaneously. The perpendicular bisector of AB passes through the midpoint of AB with gradient −1/m(AB) — equate distances PA = PB for the locus method.$cm$, sort_order = 3 where id = 'adcd967e-df66-45d0-ade1-5fc6f66427d8';
update public.flashcard_sets set description = $cm$Key terms and facts from the Coordinate Geometry study notes.$cm$ where id = 'e9b98d96-8bf8-4eb1-983c-f70911c3b90a';
update public.flashcards set front = $cm$Basic Rules$cm$, back = $cm$d/dx (k) = 0, d/dx (kx) = k$cm$, sort_order = 0 where id = 'd4d5af49-a3eb-42d5-806b-46e3cef49b69';
update public.flashcards set front = $cm$Chain Rule$cm$, back = $cm$Example: y = (3x − 1)⁵: dy/dx = 5(3x − 1)⁴ × 3 = 15(3x − 1)⁴.$cm$, sort_order = 1 where id = '10c3fe9f-ee75-4745-a232-5d578bf603d7';
update public.flashcards set front = $cm$Tangents and Normals$cm$, back = $cm$The tangent gradient at a point is dy/dx there; the normal gradient is −1/(dy/dx).$cm$, sort_order = 2 where id = '9c9deddb-1d59-4374-9b68-b415378d8296';
update public.flashcards set front = $cm$Stationary Points$cm$, back = $cm$Set dy/dx = 0, then classify with the second derivative:$cm$, sort_order = 3 where id = 'a135f7ae-2fe2-47d4-aa47-1a3e90b05a7d';
update public.flashcards set front = $cm$Rates of Change$cm$, back = $cm$dy/dx is a rate: if V = 4/3 πr³, then dV/dr = 4πr² links volume change to radius change.$cm$, sort_order = 4 where id = '4448fa33-3e53-42c2-a965-50ec58cc8a06';
update public.flashcard_sets set description = $cm$Key terms and facts from the Differentiation study notes.$cm$ where id = 'a7a4fe7e-5c57-4625-8017-9eca57f15a53';
update public.flashcards set front = $cm$Composite Functions$cm$, back = $cm$fg(x) means f(g(x)) — apply g first, then f. Order matters.$cm$, sort_order = 0 where id = 'a337e30e-bad6-4f20-842b-de850be24695';
update public.flashcards set front = $cm$Inverse Functions$cm$, back = $cm$f⁻¹ reverses f: f⁻¹f(x) = x. To find it, swap x and y in y = f(x) and rearrange.$cm$, sort_order = 1 where id = '4b8f157b-c69f-4fb0-8cef-8209f9fdb96b';
update public.flashcards set front = $cm$Transformations$cm$, back = $cm$Notation Effect on y = f(x)$cm$, sort_order = 2 where id = '6dc1d025-75e0-4baf-a8e2-327ac389ac96';
update public.flashcards set front = $cm$domain$cm$, back = $cm$to exactly one output in the$cm$, sort_order = 3 where id = 'db20144b-3adc-4fac-921c-8434af9894c0';
update public.flashcards set front = $cm$one-one$cm$, back = $cm$If not, restrict the domain (e.g. f(x) = x² for x ≥ 0 has f⁻¹(x) = √x). Graphically, y = f⁻¹(x) is the reflection of y = f(x) in the line y = x, and the range of f becomes the domain of f⁻¹.$cm$, sort_order = 4 where id = '9838a33e-1715-44eb-8cde-bac971146994';
update public.flashcard_sets set description = $cm$Key terms and facts from the Functions study notes.$cm$ where id = 'bfaef3bc-ca3d-42c2-b48a-b0c5f94bd6b3';
update public.flashcards set front = $cm$Indefinite Integrals$cm$, back = $cm$Reverse the power rule and add a constant: ∫ xⁿ dx = xⁿ⁺¹/(n+1) + c (n ≠ −1).$cm$, sort_order = 0 where id = '5479d93d-70ec-48a1-b2aa-96c561cecf85';
update public.flashcards set front = $cm$Definite Integrals$cm$, back = $cm$∫ₐᵇ f(x) dx = [F(x)]ₐᵇ = F(b) − F(a). Constants of integration cancel.$cm$, sort_order = 1 where id = 'cf881955-f8b7-4d5a-ba82-5c60900c0283';
update public.flashcards set front = $cm$Areas Under Curves$cm$, back = $cm$Area between a curve and the x-axis = ∫ₐᵇ y dx, where y ≥ 0. If the curve dips below the axis, split the integral at the roots and add the absolute values.$cm$, sort_order = 2 where id = 'dfc71886-6a05-4481-adb5-d52abf0a4779';
update public.flashcards set front = $cm$Trapezium Rule$cm$, back = $cm$A ≈ h/2 [y₀ + 2(y₁ + … + yₙ₋₁) + yₙ], h = (b − a)/n. More strips → better estimate; always an over-estimate for convex curves.$cm$, sort_order = 3 where id = '1e985c3b-721e-4333-a742-2fbc2942dc6c';
update public.flashcards set front = $cm$Examples$cm$, back = $cm$∫ x³ dx = x⁴/4 + c; ∫ 1/x dx = ln|x| + c; ∫ sin x dx = −cos x + c; ∫ e^x dx = e^x + c.$cm$, sort_order = 4 where id = '74917a52-5fc1-4139-8238-9716f4a07faa';
update public.flashcard_sets set description = $cm$Key terms and facts from the Integration study notes.$cm$ where id = '3cd7c9dc-e3da-4733-b5aa-d29f2d73f79b';
update public.flashcards set front = $cm$Completing the Square$cm$, back = $cm$Rewrite x² + bx + c as (x + b/2)² − (b/2)² + c.$cm$, sort_order = 0 where id = '032a273a-be07-4fd5-82c5-6968f9d1f518';
update public.flashcards set front = $cm$The Discriminant$cm$, back = $cm$Δ = b² − 4ac decides how the curve meets the x-axis:$cm$, sort_order = 1 where id = '77d535f4-7f83-42db-a7c9-cb71ebc7b506';
update public.flashcards set front = $cm$Quadratic Inequalities$cm$, back = $cm$Solve by sketching. For x² − 5x + 4 < 0, factorise: (x − 1)(x − 4) < 0, and the curve is below the axis between the roots, so 1 < x < 4.$cm$, sort_order = 2 where id = 'f4092d51-2a7d-4e3a-916d-d0e92d308ca6';
update public.flashcards set front = $cm$Curve and Line Intersections$cm$, back = $cm$Set the equations equal; the resulting quadratic's discriminant tells you if the line is a secant (Δ > 0), tangent (Δ = 0) or misses (Δ < 0).$cm$, sort_order = 3 where id = '94e18394-cd84-4367-9326-85528ee90707';
update public.flashcard_sets set description = $cm$Key terms and facts from the Quadratics study notes.$cm$ where id = '28bb1f09-6952-4f4e-92c4-6c35021913dd';
update public.flashcards set front = $cm$Arithmetic Progressions (AP)$cm$, back = $cm$Terms increase by a common difference d.$cm$, sort_order = 0 where id = 'c7a74c27-1e6f-4459-9901-4c8cad3019c7';
update public.flashcards set front = $cm$Geometric Progressions (GP)$cm$, back = $cm$Terms multiply by a common ratio r.$cm$, sort_order = 1 where id = 'e90e68f3-92cc-44dc-bbbd-9292ccf9684e';
update public.flashcards set front = $cm$Binomial Expansion$cm$, back = $cm$(1 + x)ⁿ = 1 + nx + n(n − 1)/2! x² + n(n − 1)(n − 2)/3! x³ + …, valid for |x| < 1.$cm$, sort_order = 2 where id = '6d4c0639-641c-4665-8811-1a81ab4c2aa3';
update public.flashcard_sets set description = $cm$Key terms and facts from the Sequences and Series study notes.$cm$ where id = '1e4df03e-206d-4f92-a025-425b627fd81c';
update public.flashcards set front = $cm$Solving Equations$cm$, back = $cm$Use the symmetry of the graphs. For sin x = 1/2 in 0 ≤ x ≤ 2π: the acute answer is π/6, and the second solution is π − π/6 = 5π/6.$cm$, sort_order = 0 where id = 'c15ae68c-07e0-40d8-9226-fa69695874f9';
update public.flashcards set front = $cm$Graphs and Transformations$cm$, back = $cm$y = a sin(bx) + c has amplitude a, period 2π/b, and vertical shift c.$cm$, sort_order = 1 where id = 'dabedc72-3826-4d6d-ae87-9fd48d3786c5';
update public.flashcards set front = $cm$Using Identities$cm$, back = $cm$If sin x = 0.6 with x acute, then cos x = √(1 − 0.36) = 0.8 (positive in the first quadrant).$cm$, sort_order = 2 where id = 'e54e3302-fe98-4bf9-9cb0-89231d109d65';
update public.flashcard_sets set description = $cm$Key terms and facts from the Trigonometry study notes.$cm$ where id = '056e492d-c0f3-49c8-9a02-be16b1fafeec';
update public.flashcards set front = $cm$Newton's Laws$cm$, back = $cm$A body stays at rest or in uniform motion unless acted on by a resultant force.$cm$, sort_order = 0 where id = '83bdcbe5-f2af-4cbf-b13e-bbf09ccf3d09';
update public.flashcards set front = $cm$Weight and Mass$cm$, back = $cm$Weight W = mg — a force in newtons; mass in kg is invariant. A 70 kg person weighs about 687 N.$cm$, sort_order = 1 where id = '3ff97b73-61f9-4f0c-8235-141b2484e7bf';
update public.flashcards set front = $cm$Momentum$cm$, back = $cm$p = mv (vector, kg m s⁻¹). Resultant force = rate of change of momentum: F = Δp/Δt.$cm$, sort_order = 2 where id = 'd92f98d0-ce84-4a89-aa88-e920cdc6e72f';
update public.flashcards set front = $cm$Friction and Connected Bodies$cm$, back = $cm$Draw free-body diagrams, then apply F = ma along each axis. For a towed car and trailer, the tow-bar tension appears as an internal pair (equal and opposite).$cm$, sort_order = 3 where id = '5c62aea2-7481-41c3-98ee-78ff9796ab24';
update public.flashcards set front = $cm$different bodies.
Example$cm$, back = $cm$a 2 kg mass with a 10 N resultant accelerates at 5 m s⁻².$cm$, sort_order = 4 where id = '70a59f92-90a5-4293-9fc1-8ec7d6bae022';
update public.flashcards set front = $cm$Conservation$cm$, back = $cm$in a collision with no external forces, total momentum is unchanged.$cm$, sort_order = 5 where id = '876e6a00-49b8-43a5-a5a8-cb5409ae85b1';
update public.flashcard_sets set description = $cm$Key terms and facts from the Dynamics study notes.$cm$ where id = '1ce6db4b-f232-4278-bd11-5f6f13344436';
update public.flashcards set front = $cm$Current and Charge$cm$, back = $cm$I = Q/t — charge per second, in amperes. Conventional current flows + to − (electrons drift the other way).$cm$, sort_order = 0 where id = '6a911898-b919-48bd-9a48-db7c43c6b941';
update public.flashcards set front = $cm$Voltage and Power$cm$, back = $cm$V = W/Q (joules per coulomb)$cm$, sort_order = 1 where id = '5d50b66e-c94e-4a29-a9b9-ed3671686262';
update public.flashcards set front = $cm$Resistance and Resistivity$cm$, back = $cm$R = V/I; R = ρL/A. Resistivity ρ is a material property (Ω m). Metals' resistance rises with temperature; thermistors' falls (NTC).$cm$, sort_order = 2 where id = 'be9691fb-e267-4be5-817a-3dfab1e298b6';
update public.flashcards set front = $cm$Series and Parallel$cm$, back = $cm$Series: same current, R_total = R₁ + R₂ + …$cm$, sort_order = 3 where id = 'c5fb3def-fa46-4602-b71a-7024dcbe4ec0';
update public.flashcards set front = $cm$EMF and Internal Resistance$cm$, back = $cm$ε = I(R + r) — some voltage is 'lost' inside the battery. Terminal voltage V = ε − Ir drops as load current rises.$cm$, sort_order = 4 where id = '3d9ff8fc-b621-4948-86b7-d5f6e7907cbb';
update public.flashcards set front = $cm$Potential Dividers$cm$, back = $cm$V_out = V_in × R₂/(R₁ + R₂). Used with LDRs/thermistors to make sensor circuits.$cm$, sort_order = 5 where id = '6099f6cc-458e-4094-843c-fc788ebf020a';
update public.flashcard_sets set description = $cm$Key terms and facts from the Electricity: D.C. Circuits study notes.$cm$ where id = 'a3f5c59d-7c8b-43c7-8763-1f8979ca8052';
update public.flashcards set front = $cm$Free-Body Diagrams$cm$, back = $cm$Draw every force on one body: weight (down), normal reactions (perpendicular to surfaces), tension (along strings), friction (opposing motion).$cm$, sort_order = 0 where id = '8b687866-a38b-4697-af21-680d04529b54';
update public.flashcards set front = $cm$Resolving Forces$cm$, back = $cm$Any force F at angle θ splits into F cos θ (along) and F sin θ (perpendicular).$cm$, sort_order = 1 where id = 'd747d949-eb2a-46ad-912f-fbe16ec5b96f';
update public.flashcards set front = $cm$Equilibrium$cm$, back = $cm$A body is in equilibrium when the resultant force is zero in every direction and the resultant moment is zero.$cm$, sort_order = 2 where id = 'ce570127-28c3-4037-ab51-39b431f19df2';
update public.flashcards set front = $cm$Moments and the Principle of Moments$cm$, back = $cm$Moment = force × perpendicular distance from the pivot.$cm$, sort_order = 3 where id = 'c725134d-bf36-4561-90c3-500fb1ac0993';
update public.flashcards set front = $cm$Centre of Gravity$cm$, back = $cm$The point where the weight appears to act. For stable equilibrium the line of action must pass through the base.$cm$, sort_order = 4 where id = '69c614c7-a613-4727-8f35-3e9bf5f09744';
update public.flashcards set front = $cm$every$cm$, back = $cm$direction and the resultant moment is zero.$cm$, sort_order = 5 where id = 'c5c4d4c0-ed57-49d3-8dad-b553312cf7be';
update public.flashcard_sets set description = $cm$Key terms and facts from the Forces and Equilibrium study notes.$cm$ where id = '919d900d-ae45-4830-8da9-109e9a3aa6f8';
update public.flashcards set front = $cm$Definitions$cm$, back = $cm$Displacement s: distance in a given direction (vector)$cm$, sort_order = 0 where id = 'fc9b21a7-e003-491a-b79a-15c5896567d7';
update public.flashcards set front = $cm$Graphs$cm$, back = $cm$Gradient of a displacement–time graph = velocity$cm$, sort_order = 1 where id = 'dbcee12e-f9cb-4ef4-aab0-b1eccdbf9cc2';
update public.flashcards set front = $cm$SUVAT (uniform acceleration only)$cm$, back = $cm$Sign convention matters: take up as positive and g = −9.81 m s⁻² for falling objects.$cm$, sort_order = 2 where id = 'e314764d-bc8e-4f91-84f5-8bbccc3d0ee4';
update public.flashcards set front = $cm$Projectiles$cm$, back = $cm$Resolve into independent components: horizontal at constant velocity (s = ut), vertical under gravity (SUVAT).$cm$, sort_order = 3 where id = '503f9773-394e-4908-8d1c-1dbe900c299f';
update public.flashcards set front = $cm$Displacement$cm$, back = $cm$s: distance in a given direction (vector)$cm$, sort_order = 4 where id = '0373b67c-7ed7-46cc-98e3-f0cd335f587d';
update public.flashcards set front = $cm$Velocity$cm$, back = $cm$v: rate of change of displacement, v = ds/dt$cm$, sort_order = 5 where id = '7f0ec7d8-161c-4354-aead-bf855fb016d3';
update public.flashcard_sets set description = $cm$Key terms and facts from the Kinematics study notes.$cm$ where id = '825f28dc-5d42-4a54-b1cb-f3e2209657b5';
update public.flashcards set front = $cm$Hooke's Law$cm$, back = $cm$Up to the limit of proportionality, F = kx — extension is proportional to load. k is the spring constant (N m⁻¹).$cm$, sort_order = 0 where id = 'dc440e81-2287-4c06-b3cc-4a8dee2e2b26';
update public.flashcards set front = $cm$Stress, Strain, Young Modulus$cm$, back = $cm$Young modulus E = σ/ε (Pa) — a material property, independent of shape$cm$, sort_order = 1 where id = 'f97edb2d-af0f-4cb5-b319-1b4dd5fd17a7';
update public.flashcards set front = $cm$Force–Extension Graphs$cm$, back = $cm$Gradient of the linear region = k$cm$, sort_order = 2 where id = 'f0c8ebf6-42b0-40c5-a87e-98dd64a58dd9';
update public.flashcards set front = $cm$Breaking Stress$cm$, back = $cm$The maximum stress a material withstands — strong materials have high breaking stress, stiff materials have high E.$cm$, sort_order = 3 where id = 'd92c9ee0-9bff-423f-86e1-f997e763522f';
update public.flashcards set front = $cm$Young modulus E = σ/ε$cm$, back = $cm$(Pa) — a material property, independent of shape$cm$, sort_order = 4 where id = '4c7ebfa3-b0f5-47f7-9529-41b3f0054860';
update public.flashcard_sets set description = $cm$Key terms and facts from the Materials: Deformation study notes.$cm$ where id = 'c00d9e5c-b51b-4f4a-bf17-00c87ec8cceb';
update public.flashcards set front = $cm$Circular Motion$cm$, back = $cm$Angular speed ω = v/r = 2π/T (rad s⁻¹). Centripetal acceleration a = v²/r = ω²r, always directed to the centre; centripetal force F = mv²/r.$cm$, sort_order = 0 where id = '67647e2d-4301-43bf-96ff-089527bf3739';
update public.flashcards set front = $cm$Gravitational Field$cm$, back = $cm$Newton's law: F = Gm₁m₂/r², G = 6.67 × 10⁻¹¹ N m² kg⁻².$cm$, sort_order = 1 where id = '066accbf-ed8b-4215-9404-53c17a0d0cc3';
update public.flashcards set front = $cm$Orbits$cm$, back = $cm$For a circular orbit, gravity supplies the centripetal force: GMm/r² = mv²/r, so v = √(GM/r) — higher orbits move slower but have longer periods (Kepler's third law: T² ∝ r³).$cm$, sort_order = 2 where id = 'af998d44-9a47-4771-9dce-ac93d4b1d9ea';
update public.flashcards set front = $cm$Potential$cm$, back = $cm$Gravitational potential φ = −GM/r (zero at infinity). Potential gradient gives field strength: g = −dφ/dr.$cm$, sort_order = 3 where id = 'f9c4b2dc-2840-4865-bba6-c25292c3f04c';
update public.flashcards set front = $cm$slower but have longer$cm$, back = $cm$periods (Kepler's third law: T² ∝ r³).$cm$, sort_order = 4 where id = 'de2db7ed-e283-48f3-99c3-50fc22066a31';
update public.flashcard_sets set description = $cm$Key terms and facts from the Motion in a Circle and Gravity study notes.$cm$ where id = 'e271fe32-a5af-4025-961e-a83a96454474';
update public.flashcards set front = $cm$The Principle of Superposition$cm$, back = $cm$When waves meet, displacements add. In phase → constructive (big amplitude); antiphase → destructive (cancellation).$cm$, sort_order = 0 where id = '126f84a9-d040-42ba-b7b6-8c937f4faa89';
update public.flashcards set front = $cm$Coherence and Path Difference$cm$, back = $cm$Two sources are coherent if they share frequency and constant phase difference. Maxima occur where path difference = nλ; minima where it = (n + ½)λ.$cm$, sort_order = 1 where id = '06d353f3-c9b5-4e36-b0d7-4342076da27d';
update public.flashcards set front = $cm$Double-Slit (Young)$cm$, back = $cm$Fringe spacing x = λD/a (D = slit–screen distance, a = slit separation).$cm$, sort_order = 2 where id = 'ac0d236e-9b93-4682-b858-496e629c518a';
update public.flashcards set front = $cm$Diffraction Grating$cm$, back = $cm$d sin θ = nθth order maximum. More slits → sharper, brighter maxima. The number of visible orders is the largest n with sin θ ≤ 1.$cm$, sort_order = 3 where id = '4270bfe6-87ea-4a5f-a8cf-7a2e33a6e268';
update public.flashcards set front = $cm$Stationary Waves$cm$, back = $cm$Two identical waves travelling opposite directions (e.g. wave + reflection) create nodes (no movement) and antinodes (max movement), spaced λ/2 apart. Strings and closed pipes resonate at f₁ = v/2L (fundamental) and harmonics.$cm$, sort_order = 4 where id = '8ec31d91-5019-44b5-858e-c54ab5ee3945';
update public.flashcard_sets set description = $cm$Key terms and facts from the Superposition study notes.$cm$ where id = '7edf67d1-2f28-4b1f-baa8-e124db29bc83';
update public.flashcards set front = $cm$Basics$cm$, back = $cm$A wave transfers energy without net transfer of matter.$cm$, sort_order = 0 where id = '18e71b29-fde6-4c5a-9df3-016b3e8f1e89';
update public.flashcards set front = $cm$The Wave Equation$cm$, back = $cm$v = fλ. Frequency f is set by the source; speed v by the medium.$cm$, sort_order = 1 where id = '1c2baaae-0857-4925-a411-8ca7fcee8462';
update public.flashcards set front = $cm$Intensity$cm$, back = $cm$I = P/A. Intensity ∝ amplitude² — doubling the amplitude quadruples the intensity.$cm$, sort_order = 2 where id = '266ff030-d7fc-45d2-a570-3543e12f534d';
update public.flashcards set front = $cm$Doppler Effect$cm$, back = $cm$Observed frequency changes with relative motion: f′ = f(v ± v_o)/(v ∓ v_s). Approaching sources sound higher.$cm$, sort_order = 3 where id = '47242691-cde8-4716-a916-9dd3f7c28d5b';
update public.flashcards set front = $cm$EM Spectrum$cm$, back = $cm$Radio → micro → IR → visible (400–700 nm) → UV → X-ray → gamma. All travel at c = 3 × 10⁸ m s⁻¹ in vacuum.$cm$, sort_order = 4 where id = 'ed3ece50-d72d-4434-afd2-e34170ba58a4';
update public.flashcards set front = $cm$Polarization$cm$, back = $cm$Only transverse waves can be polarised — proof that light is transverse. Malus' law: I = I₀ cos²θ between polariser axes.$cm$, sort_order = 5 where id = '3e7ab94e-1a06-45af-a272-1e1cf0a793f8';
update public.flashcard_sets set description = $cm$Key terms and facts from the Waves study notes.$cm$ where id = 'e7dff2a4-8ff1-4b1b-9c02-e2aa020fd343';
update public.flashcards set front = $cm$Work$cm$, back = $cm$W = Fs cos θ — force × displacement in the force's direction. Unit: joule (J).$cm$, sort_order = 0 where id = '3bddcf61-66bb-4685-8067-404ff54b13e7';
update public.flashcards set front = $cm$Energy Forms$cm$, back = $cm$Gravitational PE: Ep = mgh$cm$, sort_order = 1 where id = '110f5ee0-cd4e-48ec-9557-f6ab7eaea2b5';
update public.flashcards set front = $cm$Conservation of Energy$cm$, back = $cm$Energy changes between forms but the total stays constant (no external work).$cm$, sort_order = 2 where id = '6ae64eca-f6ad-45fe-be66-d401936f342b';
update public.flashcards set front = $cm$Power$cm$, back = $cm$P = W/t = Fv. Unit: watt (W = J s⁻¹).$cm$, sort_order = 3 where id = 'd4f57ab3-b46a-4064-b378-8d4e4779a1ad';
update public.flashcards set front = $cm$Efficiency$cm$, back = $cm$Efficiency = useful output / total input × 100%.$cm$, sort_order = 4 where id = '56941949-e2c8-4923-8932-5da35c1e8758';
update public.flashcard_sets set description = $cm$Key terms and facts from the Work, Energy and Power study notes.$cm$ where id = 'c4738d08-03c9-4492-8940-bc84efd3f4a5';
update public.flashcards set front = $cm$Linear equations$cm$, back = $cm$3(x − 2) = x + 4 → 3x − 6 = x + 4 → 2x = 10 → x = 5. With fractions, multiply through by the LCD first.$cm$, sort_order = 0 where id = '9422b905-63f4-42ab-8270-d3d3220f5758';
update public.flashcards set front = $cm$Forming equations$cm$, back = $cm$Translate shapes/situations: "rectangle length 3 cm more than width, perimeter 34" → 2w + 2(w + 3) = 34 → w = 7.$cm$, sort_order = 1 where id = '0efb0e3c-4e63-4a13-9a29-c579bcca189f';
update public.flashcards set front = $cm$Simultaneous equations$cm$, back = $cm$Elimination: 2x + y = 7 and x − y = 2 → add → 3x = 9 → x = 3, y = 1.$cm$, sort_order = 2 where id = '08afd3f6-d2ae-46ff-8df2-a917c5a6b94f';
update public.flashcards set front = $cm$Quadratics by formula$cm$, back = $cm$x = (−b ± √(b² − 4ac)) / 2a.$cm$, sort_order = 3 where id = '123be820-d7df-4aa0-b60e-65af3f6993c5';
update public.flashcards set front = $cm$Completing the square$cm$, back = $cm$x² + bx + c = (x + b/2)² − (b/2)² + c. x² − 6x + 5 = (x − 3)² − 4 → minimum at (3, −4). Use for turning points and for solving when factorising fails.$cm$, sort_order = 4 where id = '1b3a8cb1-52b4-4ad7-9c53-4ac9117a8585';
delete from public.flashcards where id = '02176687-76be-4e10-8287-f76a564d37bc';
update public.flashcard_sets set description = $cm$Key terms and facts from the Algebra ��� Equations study notes.$cm$ where id = 'b75f4c20-5d35-4994-9cf1-f432eec7fb25';
update public.flashcards set front = $cm$Straight lines$cm$, back = $cm$Gradient m = (y₂ − y₁)/(x₂ − x₁).$cm$, sort_order = 0 where id = '8b2623ee-6aa7-47d6-80cd-0e32e9fa127d';
update public.flashcards set front = $cm$Drawing curves$cm$, back = $cm$Table of values, plot, smooth curve. Parabola symmetry axis x = −b/2a. Recognise reciprocal y = 1/x (two branches) and exponential y = aˣ (through (0,1)).$cm$, sort_order = 1 where id = 'ca414d01-2fe0-4a36-bfba-155b00480bfc';
update public.flashcards set front = $cm$Interpreting$cm$, back = $cm$Roots = x-intercepts; y-intercept from x = 0.$cm$, sort_order = 2 where id = 'fafdb556-2df4-4576-b9a4-b92e1d822042';
update public.flashcards set front = $cm$Tangents and rates$cm$, back = $cm$Gradient of tangent at a point = instantaneous rate: draw a large triangle, rise/run. Area under a speed–time graph = distance (trapezium estimate).$cm$, sort_order = 3 where id = '35c6b41f-6c43-4601-9892-133e5edfbbf2';
update public.flashcards set front = $cm$Graphical solutions$cm$, back = $cm$Simultaneous: intersection points. Quadratic = line: intersections give roots. Read off carefully to the accuracy allowed.$cm$, sort_order = 4 where id = '3a7e94b8-3b52-4db6-914c-80edece07305';
delete from public.flashcards where id = 'e9266384-f570-40c7-bcb2-8444e002e39b';
update public.flashcard_sets set description = $cm$Key terms and facts from the Algebra — Graphs study notes.$cm$ where id = '0770e11f-8477-4a3f-969b-cd734e372cd3';
update public.flashcards set front = $cm$Solving$cm$, back = $cm$Like equations, but reverse the sign when multiplying/dividing by a negative: −2x ≥ 6 ⇒ x ≤ −3.$cm$, sort_order = 0 where id = '9d0813f8-20a2-47d7-b5a3-ec5391ce082d';
update public.flashcards set front = $cm$Integer solutions$cm$, back = $cm$−1 ≤ x < 4 ⇒ x ∈ {−1, 0, 1, 2, 3}. Closed endpoint for ≤/≥, open for </>.$cm$, sort_order = 1 where id = 'd1f17512-392a-4198-b526-ba4425e3d122';
update public.flashcards set front = $cm$Double inequalities$cm$, back = $cm$Handle both sides: −3 < 2x + 1 ≤ 7 → −4 < 2x ≤ 6 → −2 < x ≤ 3.$cm$, sort_order = 2 where id = '5efecd4a-df26-4025-858a-79237ad72a28';
update public.flashcards set front = $cm$Shading regions$cm$, back = $cm$Draw the boundary line: dashed for </>, solid for ≤/≥.$cm$, sort_order = 3 where id = '47442828-edb0-42a4-870b-64073ba7522d';
update public.flashcards set front = $cm$reverse the sign$cm$, back = $cm$when multiplying/dividing by a negative: −2x ≥ 6 ⇒ x ≤ −3.$cm$, sort_order = 4 where id = 'e6378f5e-f07f-40c9-b261-4ddec5abc9ef';
delete from public.flashcards where id = '286462f8-4167-486e-ac69-055ba8fce701';
update public.flashcard_sets set description = $cm$Key terms and facts from the Algebra — Inequalities study notes.$cm$ where id = 'e0750335-2d13-422e-82e3-25b64ca0fa46';
update public.flashcards set front = $cm$Linear sequences$cm$, back = $cm$nth term = a + (n − 1)d. 5, 8, 11, … → 3n + 2. Check n = 1, 2, 3.$cm$, sort_order = 0 where id = '70e23496-daaf-46f1-bcbd-35cb635ddcf3';
update public.flashcards set front = $cm$Quadratic sequences$cm$, back = $cm$Second difference = 2a → an² + bn + c. 3, 8, 15, 24 … has second difference 2 → n² + bn + c; subtract n² → 2, 4, 6, 8 → 2n; so nth term = n² + 2n.$cm$, sort_order = 1 where id = '001fe310-323b-4a6b-8731-d2a33c2267c2';
update public.flashcards set front = $cm$Special sequences$cm$, back = $cm$Even/odd, triangular (½n(n+1)), squares, cubes, Fibonacci-type (each term = sum of previous two), geometric (×r).$cm$, sort_order = 2 where id = '3b05c66c-cd2f-4bdb-b327-ed001d2a51e2';
update public.flashcards set front = $cm$Function notation$cm$, back = $cm$f(x) = 2x − 5: f(3) = 1. Solve f(x) = 11 → x = 8.$cm$, sort_order = 3 where id = 'f527077d-c033-48fc-a2fb-e9129598e682';
update public.flashcards set front = $cm$Composite functions$cm$, back = $cm$fg(x) = f(g(x)) — g first. f(x) = 2x − 5, g(x) = x²: gf(2) = g(1) = 1; fg(3) = f(9) = 13.$cm$, sort_order = 4 where id = '22a71de5-4934-48a6-aace-11008702f1c0';
update public.flashcards set front = $cm$Inverse functions$cm$, back = $cm$Swap x and y, rearrange. f(x) = 2x − 5 ⇒ f⁻¹(x) = (x + 5)/2. Domain of inverse = range of original. Verify: f⁻¹(f(x)) = x.$cm$, sort_order = 5 where id = '5f8b6b86-505b-475c-ab1a-15392c3b640a';
update public.flashcard_sets set description = $cm$Key terms and facts from the Algebra — Sequences and Functions study notes.$cm$ where id = '8393ef02-750a-428c-abd8-7dd4f92123a5';
update public.flashcards set front = $cm$Substitution$cm$, back = $cm$a = 3, b = −2: 2a² − b = 2(9) + 2 = 20. Always bracket substituted negatives.$cm$, sort_order = 0 where id = '715dbd78-48f6-4355-a094-f7a3b4d7b575';
update public.flashcards set front = $cm$Collecting like terms$cm$, back = $cm$5x + 3y − 2x + y = 3x + 4y. Terms need identical letter parts (x² and x are not like terms).$cm$, sort_order = 1 where id = 'c147bece-d7c5-455a-b3ec-078eb2d833e6';
update public.flashcards set front = $cm$Expanding$cm$, back = $cm$Single: 3(2x − 5) = 6x − 15.$cm$, sort_order = 2 where id = 'f6e7ba42-45ed-4ce1-97d2-27e22d0ef46d';
update public.flashcards set front = $cm$Factorising$cm$, back = $cm$Common factor: 6x²y − 9xy² = 3xy(2x − 3y).$cm$, sort_order = 3 where id = 'a844b914-a351-4af1-b8ac-3e47e60ccd4c';
update public.flashcards set front = $cm$Algebraic fractions$cm$, back = $cm$Factorise top and bottom fully, then cancel: (x² − 9)/(x + 3) = (x − 3). To add, use a common denominator: 1/(x+1) + 2/(x−1) = (3x + 1)/((x+1)(x−1)).$cm$, sort_order = 4 where id = '9405427a-b030-471d-a4ba-33edb1befcb6';
delete from public.flashcards where id = '34adfece-0e24-42e5-85bc-bf5f24e74dbb';
update public.flashcard_sets set description = $cm$Key terms and facts from the Algebra — Simplifying and Expanding study notes.$cm$ where id = 'e85d28e7-3221-4bbc-93af-117924df4e8a';
update public.flashcards set front = $cm$Core angle facts$cm$, back = $cm$Line 180°; point 360°; vertically opposite equal.$cm$, sort_order = 0 where id = '66abfc14-027c-4e65-a9db-52e689ba11a0';
update public.flashcards set front = $cm$Polygons$cm$, back = $cm$Interior angle sum = (n − 2) × 180°. Regular polygon: exterior = 360° ÷ n; interior = 180° − exterior.$cm$, sort_order = 1 where id = '39be67e8-544a-4d59-87fc-14f23a97f3ed';
update public.flashcards set front = $cm$Circle theorems (Extended)$cm$, back = $cm$Angle at centre = 2 × angle at circumference (same arc).$cm$, sort_order = 2 where id = '11dce240-2c69-4366-b4c4-3593e1c1cd38';
update public.flashcards set front = $cm$Algebra with angles$cm$, back = $cm$Set up equations from the theorem: cyclic quad (2x + 10) + (3x − 5) = 180 ⇒ x = 35.$cm$, sort_order = 3 where id = '09d8b5e9-fb5c-472f-bfcc-366a5cef5e44';
delete from public.flashcards where id = 'af5519d7-ffca-43a5-b5bc-3b62df3588c1';
update public.flashcard_sets set description = $cm$Key terms and facts from the Geometry — Angles and Polygons study notes.$cm$ where id = 'f411564d-8010-4b91-a19b-df34f3782f25';
update public.flashcards set front = $cm$Congruence$cm$, back = $cm$Criteria: SSS, SAS, ASA (AAS), RHS. State the criterion used when proving triangles congruent, then transfer matching sides/angles.$cm$, sort_order = 0 where id = '8d5d9fe1-55e4-40d9-a2ac-b65356aa6e62';
update public.flashcards set front = $cm$Similarity$cm$, back = $cm$Equal angles + sides in proportion. Scale factor k = corresponding new ÷ old.$cm$, sort_order = 1 where id = '43ec62bb-8b0a-49d3-aeab-47225b8f28a6';
update public.flashcards set front = $cm$Length, area, volume factors$cm$, back = $cm$Length ×k; area ×k²; volume ×k³ — including reverse problems.$cm$, sort_order = 2 where id = '7439c354-c9f5-4008-8d36-dbc96656e7c2';
update public.flashcards set front = $cm$Area/volume calculations from similarity$cm$, back = $cm$Find k from a matching length pair, then apply the right power. Watch hidden pairs (radii, heights, slants).$cm$, sort_order = 3 where id = '77c1a978-6fcc-4d06-acd9-68bf6c9e5b30';
update public.flashcards set front = $cm$Symmetry$cm$, back = $cm$Line symmetry (reflect) and rotational symmetry order — for 2-D shapes and 3-D solids (prisms, cubes, pyramids).$cm$, sort_order = 4 where id = '788af3ba-03c1-4fd1-a864-04e9f13aa885';
delete from public.flashcards where id = '06529b50-f3b6-45aa-a375-95eb3e114f65';
update public.flashcard_sets set description = $cm$Key terms and facts from the Geometry — Congruence and Similarity study notes.$cm$ where id = '9d2a09c9-8644-444f-9a26-6d7e060f8fbe';
update public.flashcards set front = $cm$Units$cm$, back = $cm$1 m² = 10 000 cm²; 1 m³ = 1 000 000 cm³; 1 litre = 1000 cm³. Convert area/volume factors carefully (square/cube the length factor).$cm$, sort_order = 0 where id = '2ab000d0-39d5-4e55-bd21-f852df0f966c';
update public.flashcards set front = $cm$Area$cm$, back = $cm$Triangle ½bh; trapezium ½(a + b)h; parallelogram bh.$cm$, sort_order = 1 where id = '0816720d-4fe9-4e0a-b43c-faa49cf0647d';
update public.flashcards set front = $cm$Volume and surface area$cm$, back = $cm$Cuboid V = lbh; prism V = cross-section × length.$cm$, sort_order = 2 where id = 'c632b506-db4a-4c9a-95bb-98bc811aaf8b';
update public.flashcards set front = $cm$Problem solving$cm$, back = $cm$Flow/filling: volume ÷ rate = time. Packing: divide volumes (check edge alignment). Nets for surface area: label every face before adding.$cm$, sort_order = 3 where id = 'e6cd283b-a56b-4b84-9612-894928e12c66';
delete from public.flashcards where id = '96735750-365d-423b-b7e9-42e8210ad274';
update public.flashcard_sets set description = $cm$Key terms and facts from the Mensuration — Area and Volume study notes.$cm$ where id = '02ed25e4-1f39-4402-984c-56956e7756a5';
update public.flashcards set front = $cm$Bearings$cm$, back = $cm$Measured clockwise from north; three figures: 065°, 128°, 300°.$cm$, sort_order = 0 where id = '384d43a2-5286-4a82-ac3a-45390c8e2a31';
update public.flashcards set front = $cm$Scale drawings$cm$, back = $cm$1 cm : 500 m style scales; measure, convert, and quote distances/bearings from your drawing to the accuracy allowed.$cm$, sort_order = 1 where id = 'febb4b44-cead-42d5-927a-dba22b7a0cd0';
update public.flashcards set front = $cm$Constructions$cm$, back = $cm$Perpendicular bisector of a segment: equal arcs from both ends, join the crossings.$cm$, sort_order = 2 where id = '5ed4ff34-a205-48f3-9584-a09e3ae89ce4';
update public.flashcards set front = $cm$Loci$cm$, back = $cm$Fixed distance from a point = circle; from a line = parallel lines with rounded ends; equidistant from two points = perpendicular bisector; from two lines = angle bisector.$cm$, sort_order = 3 where id = '9d586ed6-8eeb-4cc1-a6f9-738b9da6a15e';
delete from public.flashcards where id = '6a924b1b-dee1-4bdb-b721-7e6eadc89b8c';
update public.flashcard_sets set description = $cm$Key terms and facts from the Mensuration — Bearings and Loci study notes.$cm$ where id = '4cad9e82-1208-4088-95bc-7346d032a5c8';
update public.flashcards set front = $cm$Types of number$cm$, back = $cm$Integers : … −2, −1, 0, 1, 2 … Primes : exactly two factors; 2 is the only even prime; 1 is not prime.$cm$, sort_order = 0 where id = 'e22a1300-533e-43e4-b0a9-a610a68d196c';
update public.flashcards set front = $cm$Place value$cm$, back = $cm$In 47 382 the digit 7 has value 7000. Rounding to significant figures: keep n digits, round using the next digit (≥5 up).$cm$, sort_order = 1 where id = '380394c9-c643-41c1-a85b-3dae4edc1618';
update public.flashcards set front = $cm$Order of operations$cm$, back = $cm$BIDMAS. 3 + 4 × 2² = 3 + 16 = 19. Insert brackets yourself when translating words: "3 added to the product of 4 and 2²" = 3 + (4 × 2²).$cm$, sort_order = 2 where id = '9b9a747a-1aec-4825-9280-f42aa0be8a0b';
update public.flashcards set front = $cm$Negative numbers and calculators$cm$, back = $cm$Bracket negatives when substituting. Know the ×10ˣ, x², √, ˣ√ and fraction keys; give answers to 3 s.f. unless told otherwise.$cm$, sort_order = 3 where id = 'c561597d-a56e-4c6e-8da4-0ef0b4dbbd5b';
update public.flashcards set front = $cm$Bounds (Extended)$cm$, back = $cm$Measured to nearest u: UB = +u/2, LB = −u/2. Division p/q: max = UB p ÷ LB q .$cm$, sort_order = 4 where id = '3529b237-d2f5-40cf-a653-765cb0d3805f';
update public.flashcards set front = $cm$Integers : … −2, −1, 0, 1, 2 … Primes$cm$, back = $cm$exactly two factors; 2 is the only even prime; 1 is not prime.$cm$, sort_order = 5 where id = '37843a06-4a25-45e2-8c7d-d72a5cff8b33';
update public.flashcard_sets set description = $cm$Key terms and facts from the Number — Arithmetic and Place Value study notes.$cm$ where id = '5c7002f9-daef-436a-8030-1a1460e9f83e';
update public.flashcards set front = $cm$Conversions$cm$, back = $cm$Fraction → decimal by division; decimal → percentage ×100. Recurring decimals: let x = 0.7̄, then 10x − x = 7 ⇒ x = 7/9.$cm$, sort_order = 0 where id = '3cc08366-e37d-4b77-ba53-a1864efd20ac';
update public.flashcards set front = $cm$Operating on fractions$cm$, back = $cm$Add/subtract: common denominator. 2/3 + 1/4 = 8/12 + 3/12 = 11/12.$cm$, sort_order = 1 where id = '6a864919-af3c-4feb-b0b5-9a1e255e2727';
update public.flashcards set front = $cm$Percentage change$cm$, back = $cm$change ÷ original × 100. Increase $80 by 15%: 80 × 1.15 = $92.$cm$, sort_order = 2 where id = 'da792700-7ef0-4f05-907c-e43278be93be';
update public.flashcards set front = $cm$Reverse percentages$cm$, back = $cm$Original = new ÷ multiplier. "After a 20% increase a coat is $72" → 72 ÷ 1.2 = $60. "After 12% discount a phone is $440" → 440 ÷ 0.88 = $500.$cm$, sort_order = 3 where id = '26377958-4039-448b-8f78-a34f6852c0d6';
update public.flashcards set front = $cm$Compound change$cm$, back = $cm$Multiplierⁿ. Simple interest I = Prt/100 vs compound P(1 + r/100)ⁿ.$cm$, sort_order = 4 where id = '258f0c04-1e07-4ad2-9fa8-1ca47f03a1ca';
delete from public.flashcards where id = '47b794c0-7b95-4e7d-bc0a-493283af6e04';
update public.flashcard_sets set description = $cm$Key terms and facts from the Number — Fractions, Decimals and Percentages study notes.$cm$ where id = '527cf11d-72e9-4b03-a567-7d4823e9d333';
update public.flashcards set front = $cm$Index laws$cm$, back = $cm$aᵐ × aⁿ = aᵐ⁺ⁿ; aᵐ ÷ aⁿ = aᵐ⁻ⁿ; (aᵐ)ⁿ = aᵐⁿ$cm$, sort_order = 0 where id = '8b20e74e-82a1-4aa2-8aea-e29e0a7009db';
update public.flashcards set front = $cm$Standard form$cm$, back = $cm$47 382 = 4.7382 × 10⁴; 0.0056 = 5.6 × 10⁻³$cm$, sort_order = 1 where id = '231d3e03-420a-4459-be55-a7180d47517d';
update public.flashcards set front = $cm$Calculator use$cm$, back = $cm$Use the ×10ˣ key, not 10 ^; keep working in standard form and convert at the end. Give final answers in the form asked (often 3 s.f. standard form).$cm$, sort_order = 2 where id = '5bee368e-8851-41cd-ab93-7344dc0585ad';
update public.flashcards set front = $cm$Solving index equations$cm$, back = $cm$Match bases: 2ˣ = 32 ⇒ 2ˣ = 2⁵ ⇒ x = 5. With different bases, rewrite (8 = 2³).$cm$, sort_order = 3 where id = 'ace2d1b5-7702-4a15-bcbe-85bce3afc541';
update public.flashcards set front = $cm$Surds$cm$, back = $cm$A surd is a root that cannot be written as a rational number: √2, √3, 3√5.$cm$, sort_order = 4 where id = 'a44c8adc-3328-4dda-af91-e627911d51dd';
update public.flashcards set front = $cm$Examples$cm$, back = $cm$27^(2/3) = (³√27)² = 9; 5⁻² = 1/25; (2x³)² = 4x⁶.$cm$, sort_order = 5 where id = '296c8137-d55c-49f8-95c1-0a9882437252';
update public.flashcard_sets set description = $cm$Key terms and facts from the Number — Indices and Standard Form study notes.$cm$ where id = '9048243c-8098-447b-99ba-dfb350c2dd20';
update public.flashcards set front = $cm$Simplifying and sharing ratios$cm$, back = $cm$Scale both parts by the same factor: 250 g : 0.4 kg = 250 : 400 = 5 : 8.$cm$, sort_order = 0 where id = '2be3ff4b-2d78-463f-8158-36fe22bbc638';
update public.flashcards set front = $cm$Direct proportion$cm$, back = $cm$y = kx. Best method: find the unit value, then multiply.$cm$, sort_order = 1 where id = '435e1bfe-32c1-48ea-8809-73bcef3ecb92';
update public.flashcards set front = $cm$Inverse proportion$cm$, back = $cm$y = k/x (product constant). 4 workers 6 days ⇒ 24 worker-days ⇒ 8 workers take 3 days. Square-law: y ∝ 1/x².$cm$, sort_order = 2 where id = '59707f33-2500-4962-b35a-1b47106b9f00';
update public.flashcards set front = $cm$Rates$cm$, back = $cm$Unit rates (per item, per litre), exchange rates (draw the arrow to the target currency), best buys (price per unit, careful with multi-packs). Speed/density/pressure are compound-measure rates (Mensuration).$cm$, sort_order = 3 where id = 'd77496ce-7dfb-4a8f-92b7-be005d4c70d0';
delete from public.flashcards where id = '7e767595-bbc6-4672-b490-6f6abb617fb7';
update public.flashcard_sets set description = $cm$Key terms and facts from the Number — Ratio, Rate and Proportion study notes.$cm$ where id = '33aa9b6f-a9dd-4cd8-a2b6-2de0ec6955e0';
update public.flashcards set front = $cm$Notation$cm$, back = $cm$∈ belongs to; ∉ not in; ∅ empty set; ξ (or U) universal set; n(A) = number of elements.$cm$, sort_order = 0 where id = '2db4c1a3-0ac8-437c-b718-a7b166f837f2';
update public.flashcards set front = $cm$Venn diagrams$cm$, back = $cm$Fill the intersection first, then work outwards. Two sets: only A, both, only B, neither.$cm$, sort_order = 1 where id = 'b58a1688-4353-4c4d-af54-2a616ca4974c';
update public.flashcards set front = $cm$Shading$cm$, back = $cm$For A ∩ B′ shade where A and outside-B overlap. (A ∪ B)′ = A′ ∩ B′ (De Morgan) — check every region.$cm$, sort_order = 2 where id = 'f8f6a5a1-f7e4-4a6d-87e3-10f04978e7ae';
update public.flashcards set front = $cm$Regions algebra$cm$, back = $cm$With region variables x, y, z: use the totals to form equations, e.g. n(A ∪ B) = n(A) + n(B) − n(A ∩ B).$cm$, sort_order = 3 where id = 'b4cf1eb2-9392-4c09-ac75-fda3bbb43f6b';
update public.flashcards set front = $cm$Probability links$cm$, back = $cm$P(A ∪ B) = P(A) + P(B) − P(A ∩ B) — inclusion–exclusion from the diagram.$cm$, sort_order = 4 where id = '6a91d66d-2526-4375-9181-de7273c680a2';
update public.flashcard_sets set description = $cm$Key terms and facts from the Number — Sets study notes.$cm$ where id = '6dbd1e8d-91b2-4ebf-ad57-ad1479050ad6';
update public.flashcards set front = $cm$Correlation types$cm$, back = $cm$Positive : both increase (revision time vs score).$cm$, sort_order = 0 where id = '99870f77-9cd9-4b42-8630-a6c9378f82f5';
update public.flashcards set front = $cm$Line of best fit$cm$, back = $cm$Balance points either side of the line; it need not pass through the origin. Use two well-separated points on your line (not necessarily data points) to estimate its gradient and equation.$cm$, sort_order = 1 where id = 'd0d4b7b4-e05c-485a-ae2a-a975f23bb211';
update public.flashcards set front = $cm$Using the line$cm$, back = $cm$Interpolation (inside the data range) is reliable; extrapolation (outside) is a risk — say so if asked.$cm$, sort_order = 2 where id = '21f035b5-2be0-4427-b86c-7d0b282058d1';
update public.flashcards set front = $cm$Correlation ≠ causation$cm$, back = $cm$A third factor may drive both variables (ice-cream sales and drownings both rise with temperature). Describe relationships, don't over-claim.$cm$, sort_order = 3 where id = '80203723-6453-433f-a806-e6618a09436b';
update public.flashcards set front = $cm$Outliers$cm$, back = $cm$Points far from the trend: identify, and comment on their effect on the line; ignore them when drawing the best fit if instructed.$cm$, sort_order = 4 where id = 'b535a6b2-c485-475f-9aaf-2b25fc035072';
update public.flashcards set front = $cm$Positive$cm$, back = $cm$both increase (revision time vs score).$cm$, sort_order = 5 where id = '6393005d-86c0-4506-a011-137fc89fb8d8';
update public.flashcard_sets set description = $cm$Key terms and facts from the Scatter Diagrams and Correlation study notes.$cm$ where id = '76490045-590c-4bc1-aab3-861bb8f212aa';
update public.flashcards set front = $cm$Averages$cm$, back = $cm$Mean = Σfx/Σf from frequency tables. Median = middle value (ordered data). Mode = most frequent. Range = max − min.$cm$, sort_order = 0 where id = '44f0b070-21ef-488a-a718-2137bd089ab8';
update public.flashcards set front = $cm$Quartiles and IQR$cm$, back = $cm$Q₁ at n/4, Q₃ at 3n/4 (position); IQR = Q₃ − Q₁ — less affected by outliers than the range.$cm$, sort_order = 1 where id = '1d4c692f-beda-4628-bf72-23b2c29f0f6c';
update public.flashcards set front = $cm$Charts$cm$, back = $cm$Bar charts, pie charts (angle = fraction × 360°), time series, pictograms. Compare data sets with like-for-like totals; comment on trends.$cm$, sort_order = 2 where id = '193234f0-0841-465d-98bd-2bfaeece178b';
update public.flashcards set front = $cm$Cumulative frequency$cm$, back = $cm$Running totals vs upper class boundaries; the curve ends at (max, n). Median at n/2; Q₁/Q₃ at n/4 and 3n/4; box plot from the five-figure summary.$cm$, sort_order = 3 where id = 'c331ff9d-d8a1-4e20-af81-0c15381664a0';
update public.flashcards set front = $cm$Histograms$cm$, back = $cm$Bar area ∝ frequency: FD = frequency ÷ class width. Recover frequencies as FD × width; unequal widths need FDs on the axis.$cm$, sort_order = 4 where id = '10447fae-0b0d-466b-b95d-8b8a579dd7bb';
delete from public.flashcards where id = 'fb84266e-8716-484d-8687-e0446a3319b6';
update public.flashcard_sets set description = $cm$Key terms and facts from the Statistics — Data Handling study notes.$cm$ where id = '6d13d0f3-cc64-4333-82ab-c888694993d5';
update public.flashcards set front = $cm$Basics$cm$, back = $cm$P(event) = favourable/total; 0 ≤ P ≤ 1; P(not A) = 1 − P(A). Probabilities of a complete set sum to 1 — use to find a missing probability.$cm$, sort_order = 0 where id = '6e08b2c9-f879-4e17-99d0-0f0514044e90';
update public.flashcards set front = $cm$Combined events$cm$, back = $cm$Independent: P(A and B) = P(A) × P(B).$cm$, sort_order = 1 where id = '4ba0de47-5d07-4946-9182-67bb9d835e97';
update public.flashcards set front = $cm$Tree diagrams$cm$, back = $cm$Multiply along branches; add between outcome paths. Label end products like 4/10 × 6/9 = 4/15.$cm$, sort_order = 2 where id = '286615ec-351a-4f04-897d-11adf1cc976e';
update public.flashcards set front = $cm$Conditional probability$cm$, back = $cm$P(A|B) = P(A ∩ B)/P(B). From tree diagrams it is the "given the first branch happened" re-weighting.$cm$, sort_order = 3 where id = 'ed065d9c-570a-451a-82a9-32b5132ff3f5';
update public.flashcards set front = $cm$Relative frequency (experimental)$cm$, back = $cm$Relative frequency = successes ÷ trials. More trials → closer to theoretical probability; compare with expected counts (n × P).$cm$, sort_order = 4 where id = 'd319b301-4647-42d7-b685-951c3db31996';
delete from public.flashcards where id = 'c2759f78-cc81-4642-a9e3-2b57e7ddf0c0';
update public.flashcard_sets set description = $cm$Key terms and facts from the Statistics — Probability study notes.$cm$ where id = '06445612-40db-4f5d-803a-102e821c9ecd';
update public.flashcards set front = $cm$Transformations — full descriptions$cm$, back = $cm$Reflection : mirror line (x = 0, y = x, y = −x…).$cm$, sort_order = 0 where id = 'ac87e5e5-911c-45f5-bc27-90a0c25957e7';
update public.flashcards set front = $cm$Combined transformations$cm$, back = $cm$Apply right-to-left: "reflect in y = x, then rotate 90°" — rotate the reflected image.$cm$, sort_order = 1 where id = 'ffedc692-198f-49f9-82f7-89a08a251310';
update public.flashcards set front = $cm$Vectors$cm$, back = $cm$Column vector (x; y); magnitude = √(x² + y²).$cm$, sort_order = 2 where id = '98aa1e6a-db41-4a8d-a561-68fe934a4e66';
update public.flashcards set front = $cm$Vector geometry$cm$, back = $cm$Midpoint of AB = ½(a + b). Prove collinearity: show AB = k·BC (shared point). Prove parallelogram: AB = DC. Use route paths: AC = AB + BC.$cm$, sort_order = 3 where id = '650ed01b-1e4e-4bcc-99f0-94bf71d906ef';
update public.flashcards set front = $cm$Reflection$cm$, back = $cm$mirror line (x = 0, y = x, y = −x…).$cm$, sort_order = 4 where id = '014ab0f5-24cc-4d95-ba55-3b34e3d51263';
update public.flashcards set front = $cm$Rotation$cm$, back = $cm$centre, angle, direction (anticlockwise positive).$cm$, sort_order = 5 where id = '3fa21d94-7fdf-48b7-90ca-9267d5b284fa';
update public.flashcard_sets set description = $cm$Key terms and facts from the Transformations and Vectors study notes.$cm$ where id = '8c12d660-3cfe-4c4a-ae59-37f84d91487c';
update public.flashcards set front = $cm$The ratios$cm$, back = $cm$Label sides first (opposite, adjacent, hypotenuse) with respect to the marked angle, then choose:$cm$, sort_order = 0 where id = '1779cb01-39c5-4070-af6b-c65aadb8d20c';
update public.flashcards set front = $cm$Finding angles$cm$, back = $cm$Use inverse keys: θ = sin⁻¹(opp/hyp). tan θ = 3/4 ⇒ θ = 36.9° (1 d.p.).$cm$, sort_order = 1 where id = 'd695ef4c-7ebe-4ebb-ace2-c286f770683b';
update public.flashcards set front = $cm$Elevation and depression$cm$, back = $cm$Elevation: angle up from horizontal; depression: down. Both measured from the horizontal line at the observer.$cm$, sort_order = 2 where id = '36ac2107-f5ed-4531-b206-4f3b6ab6440b';
update public.flashcards set front = $cm$Pythagoras combinations$cm$, back = $cm$Find a missing side with Pythagoras before applying a ratio when two sides are known instead of an angle.$cm$, sort_order = 3 where id = '16d602be-d2b1-49ac-9662-77f32e2ecea0';
delete from public.flashcards where id = 'bfe257fc-02aa-4d7f-a472-8817bf9279fc';
update public.flashcard_sets set description = $cm$Key terms and facts from the Trigonometry — Right-Angled Triangles study notes.$cm$ where id = 'fd41cdf7-c32e-4775-9c05-2ff92f96d9b0';
update public.flashcards set front = $cm$Area of a triangle$cm$, back = $cm$A = ½ab sin C (C = included angle between sides a and b).$cm$, sort_order = 0 where id = '1bb225b1-c393-4e47-8452-820432cb24e6';
update public.flashcards set front = $cm$Sine rule$cm$, back = $cm$a/sin A = b/sin B = c/sin C. Use when a matching angle–side pair is known.$cm$, sort_order = 1 where id = '327487c7-547c-4e0b-9c61-52187db14f7c';
update public.flashcards set front = $cm$Cosine rule$cm$, back = $cm$a² = b² + c² − 2bc cos A. Use with two sides + included angle, or all three sides (then cos A = (b² + c² − a²)/(2bc)).$cm$, sort_order = 2 where id = '43a3569c-cfb1-4690-b310-4c37aaa3e6c2';
update public.flashcards set front = $cm$Bearing problems$cm$, back = $cm$Draw both north lines, transfer angles via parallel lines, then pick sine/cosine rule.$cm$, sort_order = 3 where id = '10140909-3711-42af-94ad-188aca855ee0';
update public.flashcards set front = $cm$3-D trigonometry$cm$, back = $cm$Identify the plane containing the required angle; use 3-D Pythagoras d² = x² + y² + z² for space diagonals; angle between a line and a plane uses the projection onto the plane.$cm$, sort_order = 4 where id = '8b582f54-c6a7-4882-b877-f51299dfa735';
delete from public.flashcards where id = 'a0ddee5f-9d99-42e6-9e34-d812079d32e1';
update public.flashcard_sets set description = $cm$Key terms and facts from the Trigonometry — Sine and Cosine Rules study notes.$cm$ where id = 'a464a554-5bfc-47cb-a929-26f4b2d09195';
update public.flashcards set front = $cm$Linked Lists$cm$, back = $cm$Each node holds a value and a pointer to the next node; a start pointer marks the head and a null marks the end. Insertion rewires two pointers — no shifting — giving O(1) insertion at a known position, but access requires walking the list, O(n).$cm$, sort_order = 0 where id = 'c2a5cbfd-4b36-4186-bb49-340f6646653d';
update public.flashcards set front = $cm$Stacks and Queues$cm$, back = $cm$A stack is LIFO (push and pop at the top); a queue is FIFO (enqueue at the rear, dequeue from the front). Both can be arrays with index pointers or linked lists. Stack uses include call stacks and expression evaluation;$cm$, sort_order = 1 where id = 'e26ab51f-5502-4590-9b15-494294862701';
update public.flashcards set front = $cm$Binary Search Trees$cm$, back = $cm$Each node has up to two children; left subtree keys are smaller, right subtree keys larger. Search, insert and (average-case) delete are O(log n). An in-order traversal outputs keys in ascending order. A degenerate (linear)$cm$, sort_order = 2 where id = '7a5f3662-fd2a-42e6-8dfb-bade66b6d59e';
insert into public.flashcards (set_id, front, back, sort_order) values ('9b378e2f-83f6-427f-9158-3f5014c14443', $cm$Hash Tables$cm$, $cm$Covered in file organisation, but as an ADT a hash table pairs a hash function with bucket storage for O(1) average access.$cm$, 3);
insert into public.flashcards (set_id, front, back, sort_order) values ('9b378e2f-83f6-427f-9158-3f5014c14443', $cm$in-order traversal$cm$, $cm$outputs keys in ascending order. A degenerate (linear) tree from sorted input degrades to O(n).$cm$, 4);
update public.flashcard_sets set description = $cm$Key terms and facts from the Abstract Data Types study notes.$cm$ where id = '9b378e2f-83f6-427f-9158-3f5014c14443';
update public.flashcards set front = $cm$User-Defined Types$cm$, back = $cm$A user-defined type is derived from existing types. An enumerated type lists named values in order: TYPE Months = (Jan, Feb, Mar ...). Internally each value is an integer index starting at 0. Pointer types store a memory address;$cm$, sort_order = 0 where id = 'b9f8a1cd-0498-434f-a4d7-5105efb9d3ac';
update public.flashcards set front = $cm$Records$cm$, back = $cm$A record groups related fields of different types under one identifier, for example a Student record with name : STRING and mark : INTEGER. Arrays of records are the standard structure for storing a table of items in memory.$cm$, sort_order = 1 where id = 'c86a9953-8266-4725-8434-a6c31bc54dc8';
update public.flashcards set front = $cm$File Organisation$cm$, back = $cm$Serial : records in insertion order; searching checks every record. Simple but slow.$cm$, sort_order = 2 where id = 'c22415d1-03c6-4db3-86a4-361d26a8ab2d';
update public.flashcards set front = $cm$Hashing$cm$, back = $cm$A common method is division hashing: Address = Key MOD TableSize. A good hash distributes keys evenly; load factor above roughly 70 percent degrades performance.$cm$, sort_order = 3 where id = 'b9ab377a-4aad-445e-94e6-42d5ebbea0d7';
update public.flashcards set front = $cm$enumerated type$cm$, back = $cm$lists named values in order: TYPE Months = (Jan, Feb, Mar ...). Internally each value is an integer index starting at 0.$cm$, sort_order = 4 where id = '83d03433-1a05-4338-a25d-15ebc1e28528';
update public.flashcards set front = $cm$Pointer types$cm$, back = $cm$store a memory address; the dereference operator returns the value at that address, which is how linked structures reference their nodes.$cm$, sort_order = 5 where id = '462cb305-2c39-4c68-86b9-0c196199be28';
update public.flashcard_sets set description = $cm$Key terms and facts from the Data Types and File Organisation study notes.$cm$ where id = 'f236c551-2062-4dd7-831b-779f826c9e72';
update public.flashcards set front = $cm$Relational Concepts$cm$, back = $cm$A table (relation) stores rows (tuples) and columns (attributes). The primary key uniquely identifies each row; a foreign key references a primary key in another table, creating the relationship. A composite key uses two or more columns together.$cm$, sort_order = 0 where id = '62097445-4344-45e3-b920-143017350244';
update public.flashcards set front = $cm$Normalisation$cm$, back = $cm$1NF : atomic values, no repeating groups.$cm$, sort_order = 1 where id = '6ec90426-a058-4b61-8a60-13fc188db9af';
update public.flashcards set front = $cm$DDL and DML$cm$, back = $cm$DDL defines structure: CREATE TABLE, ALTER TABLE, DROP. DML manipulates data: SELECT ... FROM ... WHERE, INSERT INTO, UPDATE, DELETE. Joins combine related tables: FROM Student s JOIN Enrolment e ON s.id = e.StudentID. Aggregates:$cm$, sort_order = 2 where id = '129fd95a-c934-4adb-92a9-8291e2a63f23';
update public.flashcards set front = $cm$Transactions and Concurrency$cm$, back = $cm$A transaction is a unit of work obeying ACID: Atomicity (all or nothing), Consistency (rules preserved), Isolation (concurrent transactions do not interfere), Durability (committed data survives crashes). Record locking blocks conflicting simultaneous edits;$cm$, sort_order = 3 where id = 'b06eb525-4e11-40ad-bc7b-4e175f410ebd';
update public.flashcards set front = $cm$primary key$cm$, back = $cm$uniquely identifies each row; a$cm$, sort_order = 4 where id = 'f4199778-9242-4170-9f35-00cc1e15df60';
update public.flashcards set front = $cm$foreign key$cm$, back = $cm$references a primary key in another table, creating the relationship. A composite key uses two or more columns together.$cm$, sort_order = 5 where id = 'bc4fe44d-45c5-4dad-a288-3fdb427e445e';
update public.flashcard_sets set description = $cm$Key terms and facts from the Databases and Data Definition study notes.$cm$ where id = 'fb66f416-0798-4f20-8857-210ec9889b83';
update public.flashcards set front = $cm$Paradigms$cm$, back = $cm$Procedural : programs as sequences of instructions in procedures — good for straightforward algorithms.$cm$, sort_order = 0 where id = '0791a1a8-b221-419d-a24d-7a3ff8a5e0cb';
update public.flashcards set front = $cm$Assembly Essentials$cm$, back = $cm$The opcode names the operation (LDM load, STR store, ADD, CMP compare, JMP branch, IN/OUT for I/O). The operand names the data. The assembler translates mnemonics to machine code one-to-one; two-pass assemblers resolve forward references via the symbol table.$cm$, sort_order = 1 where id = '2bc9b868-7411-44f4-b393-89db79867c02';
update public.flashcards set front = $cm$Addressing Modes$cm$, back = $cm$Immediate : operand is the constant itself, ADD #5.$cm$, sort_order = 2 where id = '452c1f65-091e-4f12-b57c-f911615534ab';
update public.flashcards set front = $cm$Fetch-Execute$cm$, back = $cm$Fetch: PC gives address, instruction loads into the CIR, PC increments. Decode: control unit interprets the opcode. Execute: the operation runs, possibly updating registers or memory. Interrupts are checked at cycle boundaries.$cm$, sort_order = 3 where id = 'aeedcdcf-34f6-4a43-97cc-020c850072de';
update public.flashcards set front = $cm$Procedural$cm$, back = $cm$programs as sequences of instructions in procedures — good for straightforward algorithms.$cm$, sort_order = 4 where id = 'c559558a-4dbe-43b4-9ebe-1780b4b51700';
update public.flashcards set front = $cm$Object-oriented$cm$, back = $cm$classes encapsulate state (attributes) and behaviour (methods); supports$cm$, sort_order = 5 where id = '8a493810-6f1a-4bb3-a4b7-547b9e9175fd';
update public.flashcard_sets set description = $cm$Key terms and facts from the Programming Paradigms and Low-Level study notes.$cm$ where id = '79119282-c5be-42e0-8b0f-43ad890e4099';
update public.flashcards set front = $cm$Simulation and Modelling$cm$, back = $cm$A simulation is a program that models a real system to test scenarios safely and cheaply: weather models, traffic flows, epidemic spread. Models use abstractions — chosen variables and equations — with a time step. Advantages:$cm$, sort_order = 0 where id = 'da9e8d5c-4053-44cd-bb0c-293e3c21102e';
update public.flashcards set front = $cm$Sensors and Signals$cm$, back = $cm$Sensors measure physical quantities: temperature (thermistor), light (LDR), pressure, humidity, sound. Most output analogue signals varying continuously; computers need digital values, so an ADC (analogue-to-digital converter) samples the signal.$cm$, sort_order = 1 where id = '3cf11f67-8e14-4e3e-b410-0e0a9434d06f';
update public.flashcards set front = $cm$Monitoring vs Control$cm$, back = $cm$Monitoring : sensors feed data to the computer, which only records, displays or raises alarms — no action taken on the environment.$cm$, sort_order = 2 where id = 'b940e1ea-7a91-471e-a080-5895fe2d6dd3';
update public.flashcards set front = $cm$Real-Time Considerations$cm$, back = $cm$Control systems are often real-time: late output can be wrong output. Sampling rate must exceed twice the highest signal frequency (Nyquist) to avoid aliasing.$cm$, sort_order = 3 where id = 'efa32ed4-fbd9-4182-92e4-2dfe754a4cbd';
update public.flashcards set front = $cm$analogue$cm$, back = $cm$signals varying continuously; computers need$cm$, sort_order = 4 where id = 'b5edefbf-aa59-4aa2-8a96-0d05f6ece3b9';
update public.flashcards set front = $cm$ADC (analogue-to-digital converter)$cm$, back = $cm$samples the signal. Resolution depends on bits — an 8-bit ADC gives 256 levels. A$cm$, sort_order = 5 where id = '7f9c2f09-df91-4cf1-8ab5-58fa9f19ea6f';
update public.flashcard_sets set description = $cm$Key terms and facts from the Simulation, Sensors and Real Data study notes.$cm$ where id = '4f973854-1af0-40b2-9dfb-3bedc8f864fb';
update public.flashcards set front = $cm$Basics$cm$, back = $cm$i² = −1. A complex number z = a + bi has real part a and imaginary part b. Two numbers are equal iff both parts match.$cm$, sort_order = 0 where id = '876bc17a-8e8e-4b4e-a752-09fcf4de96fd';
update public.flashcards set front = $cm$Conjugates$cm$, back = $cm$z̄ = a − bi. zz̄ = a² + b² (real). Dividing: multiply numerator and denominator by the conjugate.$cm$, sort_order = 1 where id = 'a21b8337-8cfe-49a3-a829-4c1dba2ebe78';
update public.flashcards set front = $cm$Argand Diagram$cm$, back = $cm$Plot z as the point (a, b). |z| = √(a² + b²) is the modulus (distance from origin); arg z = tan⁻¹(b/a) is the argument (angle). Multiply two numbers: moduli multiply, arguments add.$cm$, sort_order = 2 where id = 'e41ac17c-32ad-428b-98fe-a9675ad9820f';
update public.flashcards set front = $cm$Modulus–Argument Form$cm$, back = $cm$z = r(cos θ + i sin θ), r = |z|, θ = arg z. Useful for powers and roots.$cm$, sort_order = 3 where id = 'a6046bdc-ecd1-482a-8371-0a3c5593f356';
update public.flashcards set front = $cm$de Moivre and Roots$cm$, back = $cm$[r(cos θ + i sin θ)]ⁿ = rⁿ(cos nθ + i sin nθ).$cm$, sort_order = 4 where id = '19fd2031-ca3d-4b80-8d73-e01ad7925692';
update public.flashcard_sets set description = $cm$Key terms and facts from the Complex Numbers study notes.$cm$ where id = '21b65798-dc20-46a4-83fa-873f0e4855c1';
update public.flashcards set front = $cm$Product and Quotient Rules$cm$, back = $cm$Example: y = x² e^x gives dy/dx = 2x e^x + x² e^x = e^x(2x + x²).$cm$, sort_order = 0 where id = '4ac3074d-81a8-499b-9272-356043983dc9';
update public.flashcards set front = $cm$Standard Derivatives$cm$, back = $cm$sin x → cos x; cos x → −sin x; tan x → sec²x$cm$, sort_order = 1 where id = 'a7d9b5ca-6ea9-430f-953e-1b217ef557ab';
update public.flashcards set front = $cm$Chain Rule Everywhere$cm$, back = $cm$d/dx [ln(3x)] = 3/(3x) = 1/x; d/dx [e^(2x)] = 2e^(2x); d/dx [sin²x] = 2 sin x cos x.$cm$, sort_order = 2 where id = '68ce043d-f89e-4424-b19a-c10ca441c864';
update public.flashcards set front = $cm$Implicit Differentiation$cm$, back = $cm$Differentiate both sides w.r.t. x, treating y as a function of x (terms in y pick up dy/dx).$cm$, sort_order = 3 where id = '866d517b-8c6b-4004-afd4-062325078d21';
update public.flashcards set front = $cm$Parametric Curves$cm$, back = $cm$For x = f(t), y = g(t): dy/dx = (dy/dt)/(dx/dt).$cm$, sort_order = 4 where id = 'ebf11c78-d3ee-4c78-bf46-57d7cbdf57e5';
update public.flashcard_sets set description = $cm$Key terms and facts from the Differentiation II study notes.$cm$ where id = '48261bff-def2-4348-92a3-6ae100d7bf31';
update public.flashcards set front = $cm$Polynomial Division and the Remainder Theorem$cm$, back = $cm$Divide to rewrite p(x) = (x − a)q(x) + r. The remainder when dividing by (x − a) equals p(a).$cm$, sort_order = 0 where id = 'dd4a4a4f-10be-43b2-a245-4c170e42841d';
update public.flashcards set front = $cm$The Modulus Function$cm$, back = $cm$|x| measures distance from zero: |x| = x for x ≥ 0, −x for x < 0. Its graph is V-shaped.$cm$, sort_order = 1 where id = '14495b5a-f1de-462c-928d-4e914492e48d';
update public.flashcards set front = $cm$Partial Fractions$cm$, back = $cm$Reverse of combining fractions — needed before binomial expansion of rational functions.$cm$, sort_order = 2 where id = 'b225ecca-04e0-4bcd-b5bb-ffe5ddfca383';
update public.flashcards set front = $cm$factor$cm$, back = $cm$that is the factor theorem. Divide out fully to reduce a cubic to a quadratic and factorise completely.$cm$, sort_order = 3 where id = 'f1231eeb-c19e-46da-80e8-ed9f796a044c';
update public.flashcard_sets set description = $cm$Key terms and facts from the Further Algebra study notes.$cm$ where id = '1cce5929-18d9-4949-a25e-bd61766e7016';
update public.flashcards set front = $cm$Compound Angles$cm$, back = $cm$sin(A ± B) = sin A cos B ± cos A sin B$cm$, sort_order = 0 where id = '3b8be2c1-9ff7-4818-ab8c-459d757d80f6';
update public.flashcards set front = $cm$Double Angles$cm$, back = $cm$cos 2A = cos²A − sin²A = 2cos²A − 1 = 1 − 2sin²A$cm$, sort_order = 1 where id = '7827ff21-cc0a-4df3-945d-16675d2e3e7c';
update public.flashcards set front = $cm$The R-Form$cm$, back = $cm$a sin x + b cos x = R sin(x + α) with R = √(a² + b²) and tan α = b/a.$cm$, sort_order = 2 where id = '5c7a3762-de2d-44e5-8a99-99eb3268eaa5';
update public.flashcards set front = $cm$Reciprocal Functions$cm$, back = $cm$sec θ = 1/cos θ, cosec θ = 1/sin θ, cot θ = 1/tan θ. Key identity: 1 + cot²θ = cosec²θ.$cm$, sort_order = 3 where id = '996f7bc0-ee2f-4a94-a4f0-74b96563114a';
update public.flashcard_sets set description = $cm$Key terms and facts from the Further Trigonometry study notes.$cm$ where id = '0dc5b35e-44f8-494e-a6ed-26c37937308b';
update public.flashcards set front = $cm$Standard Integrals$cm$, back = $cm$With linear arguments: ∫ e^(3x) dx = e^(3x)/3 + c; ∫ cos 2x dx = sin 2x/2 + c.$cm$, sort_order = 0 where id = 'c7b4aa28-7999-4391-b8f8-a68ec85bb787';
update public.flashcards set front = $cm$Substitution$cm$, back = $cm$Reverse of the chain rule. For ∫ 2x e^(x²) dx, let u = x²: du = 2x dx, so the integral is ∫ e^u du = e^(x²) + c.$cm$, sort_order = 1 where id = '9bf06334-5168-4367-a033-790235a13dd9';
update public.flashcards set front = $cm$Integration by Parts$cm$, back = $cm$∫ u (dv/dx) dx = uv − ∫ v (du/dx) dx. Choose u to be the part that simplifies when differentiated (LIATE: logs, inverse trig, algebraic, trig, exponential).$cm$, sort_order = 2 where id = 'd79574a0-f8a1-4e42-a22b-a1b57b291805';
update public.flashcards set front = $cm$Partial Fractions$cm$, back = $cm$Break rational functions into pieces like ∫ 1/(x+1) dx = ln|x + 1| + c.$cm$, sort_order = 3 where id = 'ddc5705d-f57c-4dbb-adb2-231719295acb';
update public.flashcard_sets set description = $cm$Key terms and facts from the Integration II study notes.$cm$ where id = '7498d09d-4d73-4e92-a60f-2f0f76c99193';
update public.flashcards set front = $cm$The Multiplication Principle$cm$, back = $cm$If a task is done in successive stages with m, n, ... choices at each stage, the total is the product of the choices. This underpins every counting problem: a menu with 4 starters and 6 mains gives 24 meals.$cm$, sort_order = 0 where id = '8568dff7-a534-4bb4-9f98-87bb0088a070';
update public.flashcards set front = $cm$Permutations — Order Matters$cm$, back = $cm$The number of ways of arranging r objects from n distinct objects is$cm$, sort_order = 1 where id = 'ca54443d-9174-43bf-bb34-0e7f141cee77';
update public.flashcards set front = $cm$Combinations — Order Irrelevant$cm$, back = $cm$The number of ways of choosing r objects from n is$cm$, sort_order = 2 where id = '55ed49ea-b480-4025-a218-767359f5098d';
update public.flashcards set front = $cm$Restricted Permutations$cm$, back = $cm$No two specified people adjacent: arrange everyone else, then slot the restricted people into gaps. For n people with 2 who must be separated: arrange the other n − 2 (ways), then place 2 people in distinct gaps between them.$cm$, sort_order = 3 where id = '3e5c9826-1149-4f64-8b1f-86eafb7c73ee';
update public.flashcards set front = $cm$Combinations with Constraints$cm$, back = $cm$At least / at most: split into cases and add. A team of 5 from 6 boys and 5 girls with at least 3 girls is ⁵C₃⁶C₂ + ⁵C₄⁶C₁ + ⁵C₅⁶C₀.$cm$, sort_order = 4 where id = 'db4119bb-e062-41ef-b287-4dfe47813e66';
update public.flashcard_sets set description = $cm$Key terms and facts from the Permutations and Combinations study notes.$cm$ where id = '45b4d5b2-e0cd-4b82-888e-1589fb3193f9';
update public.flashcards set front = $cm$The Model$cm$, back = $cm$X ~ Po(λ) counts events in a fixed interval of time or space when events occur independently, at a constant average rate λ, and never twice at the same instant. Classic settings:$cm$, sort_order = 0 where id = 'bf1ee55f-cf64-44c3-9b65-f770ca2af225';
update public.flashcards set front = $cm$The Formula$cm$, back = $cm$P(X = r) = e^(−λ) λʳ / r! for r = 0, 1, 2, ...$cm$, sort_order = 1 where id = '501b6eff-2d79-491f-b2e3-78bebb747985';
update public.flashcards set front = $cm$Mean and Variance$cm$, back = $cm$The defining signature of the Poisson:$cm$, sort_order = 2 where id = 'd8cff297-22d4-4f43-adff-c85b3e00cb67';
update public.flashcards set front = $cm$Scaling the Interval$cm$, back = $cm$If X ~ Po(λ) per hour, then 3 hours gives Y ~ Po(3λ). Rates must be adjusted to the same interval before computing anything. Halving an interval halves λ.$cm$, sort_order = 3 where id = 'ee07367e-6048-4eca-8e51-142f40a64119';
insert into public.flashcards (set_id, front, back, sort_order) values ('e551bfc9-96bf-48fa-8002-4ce1e4309572', $cm$Adding Poissons$cm$, $cm$If X ~ Po(λ₁) and Y ~ Po(λ₂) are independent, then X + Y ~ Po(λ₁ + λ₂). Two independent queues merging into one server produce a Poisson with summed rate.$cm$, 4);
update public.flashcard_sets set description = $cm$Key terms and facts from the Poisson Distribution study notes.$cm$ where id = 'e551bfc9-96bf-48fa-8002-4ce1e4309572';
update public.flashcards set front = $cm$Basic Rules$cm$, back = $cm$For an event A with P(A) = p: 0 ≤ p ≤ 1, and P(A′) = 1 − P(A). For mutually exclusive events, probabilities add: P(A ∪ B) = P(A) + P(B). For events that can occur together, subtract the overlap:$cm$, sort_order = 0 where id = 'a5bce61b-4985-41df-ac69-741a56964715';
update public.flashcards set front = $cm$Venn Diagrams$cm$, back = $cm$Draw the universe first, then the events. Fill from the intersection outwards: if P(A) = 0.6, P(B) = 0.5 and P(A ∩ B) = 0.25, then only-A = 0.35, only-B = 0.25, neither = 0.15. Every region must sum to 1.$cm$, sort_order = 1 where id = 'b7b44723-0079-46a9-82f0-bf60a2a3ac5b';
update public.flashcards set front = $cm$Tree Diagrams$cm$, back = $cm$Branch probabilities multiply along a path; outcomes at the end of complete paths add. Draw one branch set per stage of the experiment. For two draws without replacement from a bag of 5 red and 3 blue: P(RR) = (5/8)(4/7) = 20/56.$cm$, sort_order = 2 where id = '672582b8-2f83-4e76-a18b-d744dbbef34e';
update public.flashcards set front = $cm$Conditional Probability$cm$, back = $cm$P(A | B) = P(A ∩ B)/P(B) — the probability of A given that B has occurred. The condition shrinks the sample space.$cm$, sort_order = 3 where id = '62bcdf22-b474-480d-8e9a-e97c130ad30d';
update public.flashcards set front = $cm$Independence$cm$, back = $cm$A and B are independent exactly when P(A ∩ B) = P(A)·P(B). Do not confuse independent (no influence on probabilities) with mutually exclusive (cannot co-occur). Mutually exclusive events with non-zero probabilities are never independent.$cm$, sort_order = 4 where id = '25bd6f43-5a54-4bc2-9575-36cc455a18ee';
update public.flashcard_sets set description = $cm$Key terms and facts from the Probability study notes.$cm$ where id = 'd84e1338-4daf-43f0-afbf-3c9c003bab0a';
update public.flashcards set front = $cm$Probability Distributions$cm$, back = $cm$A discrete random variable X takes values xᵢ with probabilities pᵢ where each pᵢ ≥ 0 and Σpᵢ = 1. A probability distribution can be given as a table, a formula, or a function. Any missing probability is found by subtraction.$cm$, sort_order = 0 where id = '1f56edec-6901-48a8-873d-1440604c2126';
update public.flashcards set front = $cm$Expectation$cm$, back = $cm$It is a weighted average — the long-run average value over many repetitions. E(X) need not equal any value X can actually take.$cm$, sort_order = 1 where id = 'cdab649f-4c1f-487d-9053-2d06e46f491c';
update public.flashcards set front = $cm$Variance$cm$, back = $cm$where E(X²) = Σxᵢ²pᵢ — square the values before multiplying by probabilities. The standard deviation is √Var(X).$cm$, sort_order = 2 where id = '385d1516-53d9-4a93-8c3c-73c6a10e3c69';
update public.flashcards set front = $cm$Linear Transforms$cm$, back = $cm$E(aX + b) = a·E(X) + b and Var(aX + b) = a²·Var(X)$cm$, sort_order = 3 where id = '5d5be8be-f0a8-4ca7-acce-200f1e6d56ea';
insert into public.flashcards (set_id, front, back, sort_order) values ('968b8ab5-524a-42d5-a08d-774664bfeb95', $cm$Independent Variables$cm$, $cm$If X and Y are independent: E(X + Y) = E(X) + E(Y) and Var(X + Y) = Var(X) + Var(Y). The addition rule for expectation always holds; the variance addition needs independence. The same applies to differences: Var(X − Y) = Var(X) + Var(Y)$cm$, 4);
update public.flashcard_sets set description = $cm$Key terms and facts from the Probability Distributions study notes.$cm$ where id = '968b8ab5-524a-42d5-a08d-774664bfeb95';
update public.flashcards set front = $cm$Populations, Samples, Statistics$cm$, back = $cm$A parameter describes the population (μ, σ²); a statistic describes the sample (x̄, s²). A statistic is unbiased if its expectation equals the population parameter: E(x̄) = μ always holds for the sample mean.$cm$, sort_order = 0 where id = 'e0c96347-cea4-4485-b621-3fa6d9a0d8d2';
update public.flashcards set front = $cm$Unbiased Variance$cm$, back = $cm$The estimator with divisor (n − 1) is the unbiased sample variance:$cm$, sort_order = 1 where id = '151a5ed0-8ecf-4e0a-8adc-f26e347abbfa';
update public.flashcards set front = $cm$Distribution of the Sample Mean$cm$, back = $cm$For a sample of size n from a population with mean μ and variance σ²:$cm$, sort_order = 2 where id = '35b0a29a-46c2-4030-9c1c-336c08a64584';
update public.flashcards set front = $cm$Central Limit Theorem$cm$, back = $cm$Whatever the population shape, for large n (rule of thumb n ≥ 30) the sample mean is approximately normal: x̄ ~ N(μ, σ²/n). This is why the normal appears constantly in inference.$cm$, sort_order = 3 where id = 'ba21c4f3-1607-4ef0-878e-d61bd7243851';
update public.flashcards set front = $cm$Using x̄ to Estimate$cm$, back = $cm$Given sample data, estimate μ by x̄ and σ² by the unbiased s². When the population is normal, x̄ is exactly normal for any n — the CLT is only needed for non-normal populations.$cm$, sort_order = 4 where id = 'cb4c0294-7a90-45cc-9894-c3993cba85f8';
update public.flashcard_sets set description = $cm$Key terms and facts from the Sampling and Estimation study notes.$cm$ where id = '9dfd43c1-5218-4cd4-a67b-fc1d83d38b26';
update public.flashcards set front = $cm$The Model$cm$, back = $cm$A continuous distribution with the familiar bell shape, symmetric about the mean, described by two parameters: X ~ N(μ, σ²). The curve is fully determined by μ (centre) and σ (width). Total probability is 1, and because X is continuous, P(X = a)$cm$, sort_order = 0 where id = '775f290e-bc1b-41dc-a2d8-3e14a00f50a6';
update public.flashcards set front = $cm$Standardising$cm$, back = $cm$Convert any normal variable to the standard normal Z ~ N(0, 1) with$cm$, sort_order = 1 where id = '491b8247-fa38-421e-aa61-9b1473ba4812';
update public.flashcards set front = $cm$Backwards Problems$cm$, back = $cm$Given a probability, find μ or σ. Convert the target percentile to a z-value from the table, then solve (x − μ)/σ = z.$cm$, sort_order = 2 where id = 'aeb38444-9af2-4ce1-aba3-386d7fb29d56';
update public.flashcards set front = $cm$Symmetry Shortcuts$cm$, back = $cm$P(X > μ) = 0.5. P(X < a) for a above the mean uses the complement. Tables usually give Φ(z) for z ≥ 0 only; use Φ(−z) = 1 − Φ(z).$cm$, sort_order = 3 where id = 'cd386f7a-55ee-4885-a1d8-036d8662383f';
insert into public.flashcards (set_id, front, back, sort_order) values ('a7fe8570-e9bc-4e30-8536-49eb1b33c54a', $cm$Normal Approximation to the Binomial$cm$, $cm$For large n with p near ½, X ~ B(n, p) ≈ N(np, np(1 − p)). The condition usually quoted at this level is np > 5 and n(1 − p) > 5. Apply a continuity correction: to approximate P(X ≥ 12) for a binomial, compute P(Y > 11.5) for the normal Y.$cm$, 4);
update public.flashcard_sets set description = $cm$Key terms and facts from the The Normal Distribution study notes.$cm$ where id = 'a7fe8570-e9bc-4e30-8536-49eb1b33c54a';
update public.flashcards set front = $cm$Components and Arithmetic$cm$, back = $cm$A vector a = 3i + 4j has magnitude |a| = √(3² + 4²) = 5. Parallel vectors are scalar multiples; unit vector = a/|a|.$cm$, sort_order = 0 where id = 'be7e4952-468d-43dc-8146-17cf0370a560';
update public.flashcards set front = $cm$Position and Direction$cm$, back = $cm$The line through point A with direction d: r = a + t d. Two lines are parallel if their directions are multiples.$cm$, sort_order = 1 where id = 'a1e4d5b1-8f7b-4329-b044-05db6ac60bea';
update public.flashcards set front = $cm$Scalar (Dot) Product$cm$, back = $cm$a · b = |a||b| cos θ = a₁b₁ + a₂b₂.$cm$, sort_order = 2 where id = '0b507fb4-0fb8-42d6-aadb-12949901ab90';
update public.flashcards set front = $cm$Angle Between Vectors$cm$, back = $cm$Example: between (1, 0) and (1, 1): cos θ = 1/(1 × √2), θ = 45°.$cm$, sort_order = 3 where id = '79162264-e79e-495c-b960-0839515b0491';
update public.flashcards set front = $cm$Lines and Points$cm$, back = $cm$Foot of perpendicular from P to a line, intersection of two lines, and shortest distances all come from dot products and parameter t.$cm$, sort_order = 4 where id = 'af7991ce-84c9-4c27-881f-30d8e326c61d';
update public.flashcard_sets set description = $cm$Key terms and facts from the Vectors study notes.$cm$ where id = '710df944-f531-477b-80b9-2ba65dba0648';
update public.flashcards set front = $cm$Pseudocode$cm$, back = $cm$WHILE total Assignment ←, comparison =, MOD/DIV for remainders/quotients.$cm$, sort_order = 0 where id = '0d9c45eb-96cd-4a26-ab59-eb9b5e213043';
update public.flashcards set front = $cm$Flowchart symbols$cm$, back = $cm$Terminator (oval), process (rectangle), decision (diamond), input/output (parallelogram), flow lines with arrows.$cm$, sort_order = 1 where id = '018bc253-307a-46ed-9eaf-00ee4c1401ed';
update public.flashcards set front = $cm$Standard algorithms$cm$, back = $cm$Linear search: check each item until found/end — works unsorted.$cm$, sort_order = 2 where id = '3a1d153a-b571-4a9e-b130-c6e74d35a395';
update public.flashcards set front = $cm$Trace tables$cm$, back = $cm$One column per variable; log every assignment in order; watch loop counters and reassignments.$cm$, sort_order = 3 where id = '8f7f8563-b2aa-4a4a-af09-44748967b4e5';
update public.flashcards set front = $cm$Validation vs verification$cm$, back = $cm$Validation : automatic checks on data — range (exam mark 0–100), length (password ≥ 8), type, format (postcode pattern), presence (field not empty), check digit (barcode).$cm$, sort_order = 4 where id = '6b33ae80-5952-4e22-acbe-94d6196a9ed8';
update public.flashcards set front = $cm$Testing$cm$, back = $cm$Normal (typical), abnormal (rejects invalid), boundary (extremes just inside/outside). Test data tables list input → expected output.$cm$, sort_order = 5 where id = '68429cff-c895-4770-8df3-1b8f349e36d5';
update public.flashcard_sets set description = $cm$Key terms and facts from the Algorithms & Programming study notes.$cm$ where id = '3d93ef99-c0fc-4151-a202-9cdc85b364f3';
update public.flashcards set front = $cm$Number systems$cm$, back = $cm$Binary place values 128…1; hex digits 0–9, A–F; one hex digit = one nibble (4 bits).$cm$, sort_order = 0 where id = '6c78190f-e242-49af-97dd-88f8fff450c5';
update public.flashcards set front = $cm$Two's complement (signed)$cm$, back = $cm$MSB is negative: −128 64 32 16 8 4 2 1. −5 = 1111 1011. Range 8-bit: −128…+127.$cm$, sort_order = 1 where id = 'eff123e1-84c7-498d-b1cb-b6bf0807d58b';
update public.flashcards set front = $cm$Text$cm$, back = $cm$ASCII 7-bit (128 chars) → extended sets; Unicode for all scripts (UTF-8 variable width). Character sets map codes to glyphs; uppercase/lowercase codes differ by one bit.$cm$, sort_order = 2 where id = 'a1095359-cad3-4074-ae39-e630a5690bb8';
update public.flashcards set front = $cm$Images and sound$cm$, back = $cm$Bitmap: pixels; colour depth = bits per pixel. File size (bits) = W × H × depth. Metadata (width, height, depth) stores dimensions.$cm$, sort_order = 3 where id = '9ac2ce40-bb2a-4640-a99d-c42178cd41ef';
update public.flashcards set front = $cm$Compression$cm$, back = $cm$Lossless (RLE, ZIP): exact restore — text/code must use it. RLE example: AAABBBCC → 3A3B2C; effective with runs.$cm$, sort_order = 4 where id = 'a5fdd5b2-4691-4225-aaea-eb74064ac809';
update public.flashcards set front = $cm$BCD$cm$, back = $cm$4 bits per decimal digit — 0029 → 0000 0000 0010 1001. Used in clocks/calculators; easier digit conversions, more bits than pure binary.$cm$, sort_order = 5 where id = '1cef60a3-1c90-4a23-a4c2-546705a3fe99';
update public.flashcard_sets set description = $cm$Key terms and facts from the Data Representation study notes.$cm$ where id = '6e18e59e-0542-4a31-82db-836b83c7fbdc';
update public.flashcards set front = $cm$File-based problems$cm$, back = $cm$Data repetition (wasted space, inconsistency), fixed queries, no concurrent access control — solved by a DBMS with shared, structured tables.$cm$, sort_order = 0 where id = '571c8837-7339-4be8-bb9e-aa3491440220';
update public.flashcards set front = $cm$Relational concepts$cm$, back = $cm$Table, record, field; primary key (unique); secondary key (indexed search field); foreign key links tables.$cm$, sort_order = 1 where id = '1b34e261-8191-460f-ac55-8d2a9e41b8ae';
update public.flashcards set front = $cm$SQL$cm$, back = $cm$SELECT Title, Year FROM Films$cm$, sort_order = 2 where id = 'e01b1e6d-9e6d-48af-8c4d-f8c59dd2a86c';
update public.flashcards set front = $cm$DBMS features$cm$, back = $cm$Data dictionary (schema, types, constraints), query processor, forms/reports, access rights (read/write per user), data integrity (validation rules), backup/recovery.$cm$, sort_order = 3 where id = '368c2b0c-e694-431e-b840-8c39ac858c35';
delete from public.flashcards where id = '6cbe3618-2a4d-4c61-bb3f-53a64e0f1488';
update public.flashcard_sets set description = $cm$Key terms and facts from the Database Systems study notes.$cm$ where id = '9098acae-a3f2-4054-8d98-91edace9d7c6';
update public.flashcards set front = $cm$Ethics and codes$cm$, back = $cm$ACM/IEEE-CS/BCS codes: public interest, competence, integrity, privacy. Applying: identify the principle → apply to scenario → stakeholders affected → consequences.$cm$, sort_order = 0 where id = 'ff8b1d00-97f3-4b8c-9e70-1568605d48ce';
update public.flashcards set front = $cm$Threats$cm$, back = $cm$Malware : virus (attaches, replicates via host), worm (self-spreads), trojan (disguised), spyware, ransomware.$cm$, sort_order = 1 where id = 'aac829dc-0291-43bb-bc20-2596c1d12ca9';
update public.flashcards set front = $cm$Online behaviour$cm$, back = $cm$Digital footprint, cyberbullying, fake news, privacy settings, verification of sources.$cm$, sort_order = 2 where id = '69b56e7c-20e0-4130-88cc-dd316975cbf3';
update public.flashcards set front = $cm$Wider impact$cm$, back = $cm$Employment: automation displaces roles but creates IT jobs. Environment: e-waste, energy use vs paperless efficiency. Monitoring: workplace tracking, CCTV — balance with privacy laws (GDPR-style).$cm$, sort_order = 3 where id = '7f229e4d-a7e3-4d27-bd98-368a5431a0fc';
update public.flashcards set front = $cm$Malware$cm$, back = $cm$virus (attaches, replicates via host), worm (self-spreads), trojan (disguised), spyware, ransomware.$cm$, sort_order = 4 where id = '038a99ff-131f-434b-ab82-45605a745daa';
update public.flashcards set front = $cm$Social$cm$, back = $cm$phishing (fake emails/sites), pharming (DNS/hosts redirect), shoulder surfing, brute force.$cm$, sort_order = 5 where id = 'e6b53296-dbd9-4572-ae37-5e6389a06b6e';
update public.flashcard_sets set description = $cm$Key terms and facts from the Ethics, Security & Impact study notes.$cm$ where id = '455e704e-95e1-4823-816d-1b2d5ff53510';
update public.flashcards set front = $cm$Von Neumann model$cm$, back = $cm$CPU (ALU, control unit, registers) + memory + I/O on shared buses; instructions stored as data (stored program concept).$cm$, sort_order = 0 where id = 'f142a213-ae5c-471f-aa11-2256418aadfe';
update public.flashcards set front = $cm$Registers$cm$, back = $cm$PC address of next instruction$cm$, sort_order = 1 where id = '1a9277d6-64bc-43dc-a404-e0b9684cfffd';
update public.flashcards set front = $cm$FDE cycle$cm$, back = $cm$Fetch: PC → MAR; memory → MDR → CIR; PC + 1. Decode: control unit interprets opcode. Execute: ALU/registers act. Interrupts can pause between cycles.$cm$, sort_order = 2 where id = '67d201ea-2da9-420b-ba29-da5b94f24b3d';
update public.flashcards set front = $cm$Buses and performance$cm$, back = $cm$Address bus (one-way, width ⇒ addressable memory), data bus (two-way, width ⇒ bits per transfer), control bus. Performance factors: clock speed, cache size, core count — explain the effect, not just the name.$cm$, sort_order = 3 where id = 'c6a93e1a-3382-42fa-9f3e-f78373d4b795';
update public.flashcards set front = $cm$RAM vs ROM$cm$, back = $cm$RAM: volatile, read/write, holds running programs + data. ROM: non-volatile, read-only, bootstrap/firmware. Embedded systems: dedicated microprocessors inside devices (washing machines, engines) — one function, low cost, hard to update.$cm$, sort_order = 4 where id = 'dcb71da4-64c6-417d-b1fd-1d34f10105e6';
update public.flashcards set front = $cm$Secondary storage$cm$, back = $cm$Magnetic (HDD) : platters, read/write heads; high capacity, cheap per GB, moving parts (shock-sensitive).$cm$, sort_order = 5 where id = '23830416-00c4-4952-a2e0-616a0e7e9a0c';
update public.flashcard_sets set description = $cm$Key terms and facts from the Hardware & Architecture study notes.$cm$ where id = '4863ea99-2a3b-473f-a7b8-3a40d336ccb8';
update public.flashcards set front = $cm$The six gates$cm$, back = $cm$NOT inverts. NAND = AND + invert; NOR = OR + invert; XOR = 1 when inputs differ.$cm$, sort_order = 0 where id = 'de1bf9ea-c1e9-4a75-b737-63055a0d1974';
update public.flashcards set front = $cm$Truth tables$cm$, back = $cm$2 inputs → 4 rows; 3 inputs → 8 rows. Work gate by gate, adding intermediate columns for sub-circuit outputs.$cm$, sort_order = 1 where id = '162a55c5-ccf1-4a01-82ee-85207ff6be61';
update public.flashcards set front = $cm$Describing circuits$cm$, back = $cm$Write the expression from a diagram gate by gate; annotate output of each gate (X, Y) before combining.$cm$, sort_order = 2 where id = '75304ce9-4ffa-4213-a619-d6416bd1c051';
update public.flashcards set front = $cm$Expression → truth table$cm$, back = $cm$add an intermediate column for each sub-expression before the output column.$cm$, sort_order = 3 where id = '6766fe2a-1ae6-4362-865f-dd0c95c92ea0';
update public.flashcards set front = $cm$Rules used to simplify$cm$, back = $cm$A AND 1 = A; A AND 0 = 0; A OR 1 = 1; A OR 0 = A; A AND A = A; A AND NOT A = 0; A OR NOT A = 1; NOT(NOT A) = A; X OR (X AND Y) = X. (AS extension, 9618: De Morgan's laws — NOT(A AND B) = NOT A OR NOT B and NOT(A OR B) = NOT A AND NOT B.)$cm$, sort_order = 4 where id = 'f2ae986c-1b09-4ec5-a0ee-452b094ca098';
delete from public.flashcards where id = 'dd38ec74-baf0-4262-b67e-221bb4873250';
update public.flashcard_sets set description = $cm$Key terms and facts from the Logic Gates & Boolean Logic study notes.$cm$ where id = 'c03773f6-3aad-460d-b245-9551bc332765';
update public.flashcards set front = $cm$Transmission basics$cm$, back = $cm$Serial: one bit at a time — reliable over distance, cheaper cable.$cm$, sort_order = 0 where id = '71b782ae-0bf6-42bf-b766-d828340edc3f';
update public.flashcards set front = $cm$Packets$cm$, back = $cm$Header (sender/receiver addresses, sequence number) + payload + trailer (checksum). Packet switching: routes vary, packets reassembled at destination; checksum failure → re-request. Benefits: robustness, shared lines; delays/reassembly overhead.$cm$, sort_order = 1 where id = '886c9e72-2dc3-4a92-a5c1-74ff18ff7c44';
update public.flashcards set front = $cm$Protocols$cm$, back = $cm$TCP/IP stack layers (application, transport, network, link). HTTP/HTTPS (TLS encryption), FTP (with login + commands), email: SMTP send, POP3/IMAP retrieve. Bluetooth/Wi-Fi for WPAN/WLAN.$cm$, sort_order = 2 where id = '9f10e479-3308-4d07-92c2-0517708e2080';
update public.flashcards set front = $cm$Network types & hardware$cm$, back = $cm$LAN (site) vs WAN (internet). Router (joins networks, IP), switch (MAC frames within LAN), gateway (protocol translation), NIC, WAP. MAC address (burned-in, layer 2) vs IP address (assigned, layer 3).$cm$, sort_order = 3 where id = 'cb899e30-1134-49d7-b8bb-7137106334a6';
update public.flashcards set front = $cm$Security in transmission$cm$, back = $cm$Encryption scrambles plaintext → ciphertext (key needed); HTTPS = HTTP over TLS; firewall packet filtering by port/IP; authentication (user+pass, 2FA); access levels.$cm$, sort_order = 4 where id = '78ce38c3-a0c8-4d4a-805e-1f96305fbf74';
delete from public.flashcards where id = 'd5b9752c-8846-434d-9aef-51dc25876882';
update public.flashcard_sets set description = $cm$Key terms and facts from the Networking & Communication study notes.$cm$ where id = '75e23a9f-6953-4d9b-a2c6-6db249ef6d40';
update public.flashcards set front = $cm$What an OS does$cm$, back = $cm$Manages memory, processes/files, I/O via drivers, security (users, permissions), and provides the UI (CLI/GUI) between user, applications and hardware.$cm$, sort_order = 0 where id = 'e95dfe7e-2ab2-4729-b424-5c875e9ac051';
update public.flashcards set front = $cm$Memory and process management$cm$, back = $cm$Paging/segmentation move programs in/out; virtual memory extends RAM to disk when RAM is full.$cm$, sort_order = 1 where id = '69172bb5-b07a-42bd-8b3e-f293627be989';
update public.flashcards set front = $cm$Interrupts and buffers$cm$, back = $cm$Interrupts signal events (I/O complete, timer); CPU saves context, services via ISR, resumes. Buffers hold data in transit (printing) so slow devices don't block the CPU; spooling queues jobs.$cm$, sort_order = 2 where id = '49bab2f0-4139-439f-884b-7a68f3aef409';
update public.flashcards set front = $cm$Utility software$cm$, back = $cm$Disk formatter, defragmenter (reduces head movement on HDDs; unnecessary for SSD), backup scheduler, compression, antivirus, file compression.$cm$, sort_order = 3 where id = '70acca7f-d500-401f-8318-604dd3d38a5b';
update public.flashcards set front = $cm$UI and drivers$cm$, back = $cm$CLI: precise, scriptable, low overhead. GUI: icons/windows, discoverable, more resources. Device drivers translate OS calls to hardware specifics — each device needs its own.$cm$, sort_order = 4 where id = 'e9b2ef35-26ca-4ae0-96fe-b90e351e4935';
delete from public.flashcards where id = 'cec547a0-b8dc-4116-acab-1f32a3b6c88d';
update public.flashcard_sets set description = $cm$Key terms and facts from the Operating Systems study notes.$cm$ where id = 'e81f8f6e-40e2-4374-95a2-7c71e27fecca';
update public.flashcards set front = $cm$Basics$cm$, back = $cm$Constants vs variables; types: INTEGER, REAL, CHAR, STRING, BOOLEAN, DATE; casting between them. Declaration with meaningful names.$cm$, sort_order = 0 where id = '36bb75a3-3617-40e6-86bb-fb8a8f88c22f';
update public.flashcards set front = $cm$Selection and iteration$cm$, back = $cm$OTHERWISE : OUTPUT "keep going"$cm$, sort_order = 1 where id = '4586b7d8-66c0-47f9-b6b0-65b85fbfec08';
update public.flashcards set front = $cm$Arrays$cm$, back = $cm$Fixed size, indexed (0- or 1-based per spec); 2D arrays: row, column. Bounds errors when index leaves range. Traversal with FOR loops.$cm$, sort_order = 2 where id = '45a5eabb-c8ad-4860-bcfc-34c96c3de5b8';
update public.flashcards set front = $cm$Files$cm$, back = $cm$OPENFILE "data.txt" FOR READ$cm$, sort_order = 3 where id = 'a385e30c-6b28-483f-b2a0-8a069f19dbb2';
update public.flashcards set front = $cm$Subroutines$cm$, back = $cm$Procedure (no return) vs function (returns value). Parameters by value (copy) vs reference (original). Local scope inside; global shared — declare deliberately, avoid overuse.$cm$, sort_order = 4 where id = 'd01e2c91-4de5-4a54-a302-4a62401ec691';
update public.flashcards set front = $cm$IDE tools$cm$, back = $cm$Syntax highlighting, autocompletion, breakpoints, single stepping, variable watch — name the tool and its debugging benefit.$cm$, sort_order = 5 where id = '5e2263f6-a63a-45b9-8e9f-1c6bcda7be9c';
update public.flashcard_sets set description = $cm$Key terms and facts from the Programming Concepts study notes.$cm$ where id = '48e7d9b7-4a77-462a-9cbd-6715f5116089';
update public.flashcards set front = $cm$AI characteristics$cm$, back = $cm$Systems exhibiting: planning, learning, reasoning, problem-solving, perception, knowledge representation. Narrow (task-specific) vs general AI distinction for discussion answers.$cm$, sort_order = 0 where id = '0d010b9b-e02e-4e6a-980b-dc3f78d8ab79';
update public.flashcards set front = $cm$Machine learning$cm$, back = $cm$Supervised (labelled data — spam filters), unsupervised (clusters — segmentation), reinforcement (rewards — game agents). Training/evaluation loop: train on a set, test on unseen data; overfitting = memorising rather than generalising.$cm$, sort_order = 1 where id = '9b9396d6-e986-44a6-b915-9684fa36d0db';
update public.flashcards set front = $cm$Robotics$cm$, back = $cm$Components: sensors (input), processors (decision), actuators/motors (output), power. Examples: manufacturing arms, delivery drones, autonomous vehicles (LIDAR + vision). Benefits: precision, 24/7 operation, dangerous jobs; concerns:$cm$, sort_order = 2 where id = 'bad61355-a580-4f38-b34b-97b0c9cbb304';
update public.flashcards set front = $cm$Automated systems & simulation$cm$, back = $cm$Sensors → processor → actuators loops (greenhouses, traffic lights, self-checkouts). Simulation models real systems cheaply and safely (flight training, weather, crash tests) — limitations: model quality, missing variables.$cm$, sort_order = 3 where id = 'eb2dec39-9158-4e0f-8501-13753aff561c';
update public.flashcards set front = $cm$Ethics of AI$cm$, back = $cm$Bias from unrepresentative training data; opacity of decisions; accountability for errors; privacy of training data; effect on employment.$cm$, sort_order = 4 where id = '45968ad4-e00a-480d-b296-f3bf131d1113';
update public.flashcard_sets set description = $cm$Key terms and facts from the Robotics & AI study notes.$cm$ where id = 'e8b72d9a-9879-43c2-897b-42e2576de483';
update public.flashcards set front = $cm$HTML$cm$, back = $cm$<head><title>Page</title></head>$cm$, sort_order = 0 where id = 'e3e67718-9bd3-4863-bc57-248bd3e7d764';
update public.flashcards set front = $cm$CSS$cm$, back = $cm$p { color: red; font-size: 14px; }$cm$, sort_order = 1 where id = '4801c3cc-4961-45d6-ad1b-fc625bb828cf';
update public.flashcards set front = $cm$JavaScript and the DOM$cm$, back = $cm$document.getElementById("demo").innerHTML = "Hello";$cm$, sort_order = 2 where id = '0b7a5338-dbf9-4cbc-8c04-654102caf3c1';
update public.flashcards set front = $cm$How pages load$cm$, back = $cm$URL → DNS lookup → server request → HTML parsed → assets fetched → DOM built → render. Layers: structure (HTML) → presentation (CSS) → behaviour (JS).$cm$, sort_order = 3 where id = 'da6c2ef9-76e6-4bdf-a3c7-3e0d7888738b';
delete from public.flashcards where id = '68fe15dd-6cb1-40c8-8e84-9dd792f4599c';
update public.flashcard_sets set description = $cm$Key terms and facts from the Web Technologies study notes.$cm$ where id = '523d46a0-2a1f-411f-a791-464a78deb79e';
update public.flashcards set front = $cm$Earth, Moon, Sun$cm$, back = $cm$Earth rotates 24 h (day/night), orbits 365¼ d (year + leap). Moon orbits Earth ~27.3 d; phases from viewing angle; lunar/solar eclipses when aligned. Seasons from axial tilt (23.5°), not distance.$cm$, sort_order = 0 where id = '94e1a334-6e19-42a0-a893-4554a08ef627';
update public.flashcards set front = $cm$Solar system$cm$, back = $cm$Planets (Mercury → Neptune), dwarf planets (Pluto), moons, asteroids, comets (eccentric orbits, tails away from Sun), natural satellites. Gravity keeps orbits; orbital speed & radius relate to the central mass.$cm$, sort_order = 1 where id = 'c12a4bb0-240a-49be-ab95-27040efd51fa';
update public.flashcards set front = $cm$Orbital motion$cm$, back = $cm$Orbital speed v = 2πr/T. T grows with r (Kepler trend). Comets speed up near the Sun (ellipse, Sun at focus).$cm$, sort_order = 2 where id = '3d405ef7-84a6-49b4-861f-7cff62d77f15';
update public.flashcards set front = $cm$Stars (Extended)$cm$, back = $cm$Star formation: nebula → protostar (gravity, KE→thermal) → main sequence (hydrogen fusion: H→He, radiation pressure balances gravity) → red giant → white dwarf (Sun-mass) or supergiant → supernova → neutron star/black hole (massive stars).$cm$, sort_order = 3 where id = '57013a09-2bf0-47f4-80bc-7db6838291d1';
update public.flashcards set front = $cm$Universe (Extended)$cm$, back = $cm$The Sun is one star in the Milky Way; the Milky Way is one of billions of galaxies. Redshift: receding galaxies show stretched wavelengths → the Universe is expanding → Big Bang model; CMB is the afterglow. Hubble: farther ⇒ faster recession.$cm$, sort_order = 4 where id = '04b9c34b-9840-4af5-baee-cb0cad192241';
update public.flashcards set front = $cm$Scales$cm$, back = $cm$light-year = distance light travels in a year (9.5 × 10¹⁵ m); astronomical unit = Earth–Sun distance (1.5 × 10¹¹ m).$cm$, sort_order = 5 where id = 'd963561c-1729-4369-8f1e-81719332b40c';
update public.flashcard_sets set description = $cm$Key terms and facts from the Earth & Space study notes.$cm$ where id = '831cdc0c-4b12-4f8e-a7b9-93f1201c0fa9';
update public.flashcards set front = $cm$Circuit symbols & current$cm$, back = $cm$Conventional current: + → − (electron flow opposite). I = Q/t. Ammeter in series; voltmeter in parallel.$cm$, sort_order = 0 where id = '82980c47-f2ba-4e6c-a782-52569f30bf29';
update public.flashcards set front = $cm$Current, p.d., e.m.f.$cm$, back = $cm$Current: rate of charge flow; same everywhere in series.$cm$, sort_order = 1 where id = '5bd669d8-3fd8-4d70-8874-71d7b0a90dbb';
update public.flashcards set front = $cm$Resistance$cm$, back = $cm$R = V/I. Ohmic conductor: V ∝ I at constant temperature.$cm$, sort_order = 2 where id = '149ecfc2-9542-4bd2-b1a8-b84e10c01329';
update public.flashcards set front = $cm$Components$cm$, back = $cm$Fixed/variable resistors, LDR (light ↑ R ↓), thermistor (T ↑ R ↓), diode/LED (one-way), relay, filament lamp (R grows as T rises — V–I curve flattens).$cm$, sort_order = 3 where id = '732c81a9-113d-4eb8-a8ee-91d8a9094569';
update public.flashcards set front = $cm$Power and energy$cm$, back = $cm$P = VI = I²R = V²/R; E = VIt. Fuse rating just above normal current; earth wire, double insulation, circuit breakers (trip quickly, resettable).$cm$, sort_order = 4 where id = 'f8ff8b45-678d-4d45-a151-bf12473cf051';
update public.flashcards set front = $cm$Digital electronics basics (syllabus 4.5 context)$cm$, back = $cm$Analogue vs digital; logic gates drive outputs from inputs (see CS link); sensors feed comparator-style circuits.$cm$, sort_order = 5 where id = '67823a88-a3f5-4db9-a703-964360925b13';
update public.flashcard_sets set description = $cm$Key terms and facts from the Electricity & Circuits study notes.$cm$ where id = '1a50a9c6-ffa0-40cf-9b24-dbf5db8953a7';
update public.flashcards set front = $cm$Energy stores & transfers$cm$, back = $cm$Stores: kinetic, gravitational, elastic, chemical, nuclear, thermal. Transfer mechanisms: mechanically, electrically, heating, waves. Energy is conserved overall; transfers via work done.$cm$, sort_order = 0 where id = 'c0546a35-faaf-44fe-90f6-e73b947f5bde';
update public.flashcards set front = $cm$Formulas$cm$, back = $cm$Work W = Fd (force along displacement, joules).$cm$, sort_order = 1 where id = '45978678-a86b-43d3-a643-533ef24ed2ee';
update public.flashcards set front = $cm$Energy sources$cm$, back = $cm$Renewable: solar, wind, hydro, geothermal, biofuel, tidal — replenished. Non-renewable: fossil fuels, nuclear — finite. Discuss reliability, cost, pollution for "evaluate" questions.$cm$, sort_order = 2 where id = 'b75d67ae-8732-46eb-ad40-e822cf8c2e46';
update public.flashcards set front = $cm$Efficiency$cm$, back = $cm$Efficiency = useful output ÷ total input (×100%). Sankey diagrams show losses.$cm$, sort_order = 3 where id = '79512203-0fd5-4a7f-b7af-05594f7f6e54';
update public.flashcards set front = $cm$Energy-chain problems$cm$, back = $cm$Equating KE loss to PE gain: v = √(2gh) for frictionless drop; braking distance grows with v².$cm$, sort_order = 4 where id = 'b0dc792e-2616-4623-8e47-0cc42dfb050a';
delete from public.flashcards where id = '92c92660-8109-4390-80bc-30a34b58df91';
update public.flashcard_sets set description = $cm$Key terms and facts from the Energy, Work & Power study notes.$cm$ where id = '31a9d2a1-e5fe-4c70-a9da-d39861746fed';
update public.flashcards set front = $cm$Kinematics$cm$, back = $cm$Speed = distance/time; average speed = (u + v)/2 for uniform acceleration.$cm$, sort_order = 0 where id = '8ae388ad-49c1-443d-8dd5-c58eb84f3aec';
update public.flashcards set front = $cm$Motion graphs$cm$, back = $cm$Distance–time: gradient = speed.$cm$, sort_order = 1 where id = 'f7fe4a84-f5b8-4f0d-95a7-23fdadf01d4a';
update public.flashcards set front = $cm$Mass, weight, density$cm$, back = $cm$W = mg (g ≈ 10 N/kg). Weight acts at the centre of mass; mass is invariant. Density ρ = m/V.$cm$, sort_order = 2 where id = 'a6821bbe-da36-414e-91ad-6f177ccded82';
update public.flashcards set front = $cm$Newton's laws and resultant force$cm$, back = $cm$Resultant: colinear addition/subtraction; perpendicular by Pythagoras.$cm$, sort_order = 3 where id = 'd0c0573c-83a8-4dcc-9716-5485e3d51030';
update public.flashcards set front = $cm$Momentum (Extended)$cm$, back = $cm$p = mv; impulse Ft = Δ(mv); conservation: Σp before = Σp after (explosions, collisions).$cm$, sort_order = 4 where id = '0a5a27eb-e4e1-429c-85d6-bdcf0476257f';
update public.flashcards set front = $cm$Moments and equilibrium$cm$, back = $cm$Moment = F × perpendicular distance from pivot.$cm$, sort_order = 5 where id = 'c844d72e-6dd5-409a-9726-d610e621905e';
update public.flashcard_sets set description = $cm$Key terms and facts from the Forces & Motion study notes.$cm$ where id = '87d5bf34-c749-452e-87ef-be044fd8549b';
update public.flashcards set front = $cm$Magnets and fields$cm$, back = $cm$Iron/steel/cobalt/nickel; like poles repel. Field lines exit N, enter S; compass plotting; plotting compass aligns with field. Induced magnetism: iron (temporary) vs steel (permanent).$cm$, sort_order = 0 where id = '7392116b-9d50-4b13-9e1e-2529ac154f5a';
update public.flashcards set front = $cm$Electromagnets$cm$, back = $cm$Solenoid field like a bar magnet; strength ↑ with current, turns, iron core. Uses: relays, scrapyard crane, electric bell, speaker. Hard/soft magnetic materials choose permanent vs core use.$cm$, sort_order = 1 where id = '58050978-b6e8-43bc-8cde-6f99f5f109f6';
update public.flashcards set front = $cm$Force on a current-carrying conductor$cm$, back = $cm$F = BIL, direction by Fleming's left hand (fIeld, current, force). Reversing current or field reverses force. D.C. motor: coil, commutator reverses current each half-turn for continuous rotation; speed/torque ↑ with current, field strength, turns/area.$cm$, sort_order = 2 where id = '7a40bf51-a18c-4c72-b828-88c3c73baeb2';
update public.flashcards set front = $cm$Electromagnetic induction (Extended)$cm$, back = $cm$Induced e.m.f. when a conductor cuts field lines or flux changes. Fleming's right hand (generator). Factors: speed, field strength, turns. A.C. generator: slip rings; dynamo effect; Lenz's law opposes change (direction of induced current).$cm$, sort_order = 3 where id = '677b3a3c-0314-45e0-9b57-c8ff499aae62';
update public.flashcards set front = $cm$Transformers (Extended)$cm$, back = $cm$V p /V s = N p /N s ; P in ≈ P out (100% assumed): I p V p = I s V s . Step-up raises V, lowers I → lower I²R transmission losses; a.c. required (changing flux).$cm$, sort_order = 4 where id = '0ab86167-7e57-46e3-9de2-e49ebf191e11';
delete from public.flashcards where id = '117e01cb-f7e7-464f-9915-4cffe75fe297';
update public.flashcard_sets set description = $cm$Key terms and facts from the Magnetism & Electromagnetism study notes.$cm$ where id = '885776d4-313d-4b22-9d4a-ff3ba4192fac';
update public.flashcards set front = $cm$Measuring$cm$, back = $cm$Length: ruler (mm), vernier calipers (0.1 mm / 0.01 cm), micrometer screw gauge (0.01 mm).$cm$, sort_order = 0 where id = 'd391c625-c684-473b-b43b-a8ecf1b00cb1';
update public.flashcards set front = $cm$SI units and prefixes$cm$, back = $cm$temperature kelvin (°C used) K$cm$, sort_order = 1 where id = '6218cda0-e164-497b-9dc9-5daf589e5ca4';
update public.flashcards set front = $cm$Scalars and vectors$cm$, back = $cm$Scalars: distance, speed, mass, energy, time. Vectors: displacement, velocity, acceleration, force, weight, momentum. Vector addition by scale diagram (tip-to-tail) or by components.$cm$, sort_order = 2 where id = 'bece778c-f296-48f3-9056-13287d0bb508';
update public.flashcards set front = $cm$Density$cm$, back = $cm$ρ = m/V (kg/m³ or g/cm³; 1 g/cm³ = 1000 kg/m³). Determining: mass on balance; volume by displacement. Floating: ρ object < ρ fluid .$cm$, sort_order = 3 where id = '7e32b750-e77f-4b2f-a03a-009a3726af6d';
update public.flashcards set front = $cm$Accuracy and improvements$cm$, back = $cm$Avoid parallax (eye level with reading), zero errors (subtract the zero reading), measure multiple laps for small times. Suggest improvements by naming the error and the fix.$cm$, sort_order = 4 where id = 'b18d91f0-4237-454b-80bd-7b1ba1b8f2aa';
delete from public.flashcards where id = 'f08b06fb-d77e-4593-bd62-57ef180788ec';
update public.flashcard_sets set description = $cm$Key terms and facts from the Measurement & Units study notes.$cm$ where id = '2cc96d0b-014c-40b7-8ae1-2e466c1d3647';
update public.flashcards set front = $cm$The nuclear model$cm$, back = $cm$Nucleus (protons +, neutrons 0) with orbiting electrons (−). Nuclide notation ᴬ_Z X. Isotopes: same Z, different A. Rutherford scattering established the nuclear model; proton number Z, nucleon number A.$cm$, sort_order = 0 where id = '70443af7-cd96-44fc-bbb7-f2b552ace1f5';
update public.flashcards set front = $cm$Radiation types$cm$, back = $cm$Type Nature Range (air) Stopped by$cm$, sort_order = 1 where id = '64ab5952-0a20-456e-8e55-5645ead4f510';
update public.flashcards set front = $cm$Decay equations$cm$, back = $cm$α: A −4, Z −2 (e.g. ²³⁸₉₂U → ²³⁴₉₀Th + α).$cm$, sort_order = 2 where id = '2f2c868f-c7dc-4b77-a1cb-06d2039d5bda';
update public.flashcards set front = $cm$Half-life$cm$, back = $cm$Time for half the unstable nuclei to decay (random process). Read from a decay curve or count halves: 80 → 40 → 20 over two half-lives.$cm$, sort_order = 3 where id = '49cb1aa6-b503-4cff-9d5d-c6569eebf89c';
update public.flashcards set front = $cm$Safety and uses$cm$, back = $cm$Uses: medical tracers (β/γ), sterilisation, thickness gauge (β), dating (C-14), smoke alarms (α). Safety: distance, time, shielding, wear badges, store in lead. Handle with tongs; never point at people.$cm$, sort_order = 4 where id = 'add19a13-7331-4576-b6d8-b1b7c5a20ffd';
update public.flashcards set front = $cm$Fission and fusion (Extended)$cm$, back = $cm$Fission: heavy nucleus splits (U-235 + neutron), chain reaction controlled by moderators/control rods — power stations. Fusion: light nuclei join (stellar) — needs huge T/P; releases more energy per kg; no long-lived waste.$cm$, sort_order = 5 where id = '92d107af-9e79-44af-975e-ff3fe19c2f01';
update public.flashcard_sets set description = $cm$Key terms and facts from the Nuclear Physics study notes.$cm$ where id = 'cd385889-515c-4680-b051-d794d6c084b0';
update public.flashcards set front = $cm$Pressure basics$cm$, back = $cm$p = F/A (Pa = N/m²). Increase F or decrease A to raise pressure; explain applications (snowshoes, knives, hydraulic press).$cm$, sort_order = 0 where id = 'f6d709f5-c493-47d4-9aab-15e5650ea22c';
update public.flashcards set front = $cm$Liquids$cm$, back = $cm$Pressure increases with depth: p = ρgh (Extended).$cm$, sort_order = 1 where id = '69e5541b-c127-4f80-a9f4-1ce34079898a';
update public.flashcards set front = $cm$Atmospheric pressure$cm$, back = $cm$~10⁵ Pa at sea level; demonstrated by collapsing can, mercury barometer 760 mmHg; decreases with altitude.$cm$, sort_order = 2 where id = 'd752ac58-5200-43c2-b32e-8cf1a201e530';
update public.flashcards set front = $cm$Density revisited$cm$, back = $cm$ρ = m/V; floating condition; upthrust = weight of displaced fluid (qualitative).$cm$, sort_order = 3 where id = 'bba13145-5407-4c19-8f84-70f45bba5177';
update public.flashcards set front = $cm$Gas pressure (particle model)$cm$, back = $cm$Particles collide with walls → force per area. Volume ↓ at same T ⇒ pressure ↑ (more frequent collisions). Temperature ↑ ⇒ faster particles ⇒ more frequent, harder impacts.$cm$, sort_order = 4 where id = '6a871e34-21f0-460d-b792-5e8984ebfd0b';
delete from public.flashcards where id = '343e746a-d56b-4c79-a2a3-3cbc801899b1';
update public.flashcard_sets set description = $cm$Key terms and facts from the Pressure & Density study notes.$cm$ where id = 'd4f947db-3e96-4f3e-a58f-03f3030285c3';
update public.flashcards set front = $cm$Kinetic model$cm$, back = $cm$Solid: fixed positions, vibrate — fixed shape/volume. Liquid: move around, touching — fixed volume, flows. Gas: far apart, fast random motion — fills container. Brownian motion evidences random molecular motion.$cm$, sort_order = 0 where id = '89252f11-9d13-4441-b85f-9106fd85f8b7';
update public.flashcards set front = $cm$Gas pressure and temperature$cm$, back = $cm$Pressure from wall collisions. Heating at fixed volume → faster particles → more frequent, harder collisions → higher pressure.$cm$, sort_order = 1 where id = 'ef9a51f2-c786-4546-8961-83fc0a8f2866';
update public.flashcards set front = $cm$Thermal expansion$cm$, back = $cm$Heating → particles vibrate more → solids expand slightly (gases expand most). Applications: bimetallic strip (fire alarm/thermostat), gaps in bridges/rails; the liquid-in-glass thermometer.$cm$, sort_order = 2 where id = '53f75dfe-65f2-4d2e-9ea9-5deaa4abb3e2';
update public.flashcards set front = $cm$Specific heat capacity$cm$, back = $cm$c = ΔE/(mΔθ). Heating: ΔE = mcΔθ.$cm$, sort_order = 3 where id = 'bbd26e71-4faf-4a96-adec-569706e5e1c3';
update public.flashcards set front = $cm$State changes$cm$, back = $cm$Melting/boiling at fixed temperature despite heating (energy breaks bonds, not temperature). Condensation/ freezing release energy. Impurities raise melting point of mixtures/lower freezing; boiling needs nucleation.$cm$, sort_order = 4 where id = '26a8287d-3419-4fdb-a68a-f359f85bc783';
update public.flashcards set front = $cm$Transfer: conduction, convection, radiation$cm$, back = $cm$Conduction : mainly metals (delocalised electrons + lattice vibration); non-metals poor; insulators trap air.$cm$, sort_order = 5 where id = '6376ad61-48b5-44a3-a315-7b91f84f87fa';
update public.flashcard_sets set description = $cm$Key terms and facts from the Thermal Physics study notes.$cm$ where id = 'a879a465-9acf-4470-b36f-b0ffec1b0cdf';
update public.flashcards set front = $cm$Wave basics$cm$, back = $cm$v = fλ. Transverse (oscillation ⊥ travel — light, water, S-waves) vs longitudinal (parallel — sound, P-waves). Amplitude, wavelength, frequency f = 1/T; wavefront diagrams.$cm$, sort_order = 0 where id = 'abde5f1f-56a4-4a5c-a93e-5721b98e22ac';
update public.flashcards set front = $cm$Ripple tank behaviours$cm$, back = $cm$Reflection : angle in = angle out; speed/frequency unchanged, direction changes.$cm$, sort_order = 1 where id = '3457a5b4-d3a5-4e09-9b24-24cf77435b16';
update public.flashcards set front = $cm$Electromagnetic spectrum (order)$cm$, back = $cm$Radio → micro → IR → visible (red 700 nm – violet 400 nm) → UV → X → gamma. All travel at 3 × 10⁸ m/s in vacuum; transverse; uses and dangers (IR heating; UV skin; X/gamma ionising).$cm$, sort_order = 2 where id = 'd64fbfb8-de45-4743-acec-38e3d458c07e';
update public.flashcards set front = $cm$Sound$cm$, back = $cm$Longitudinal; needs a medium (bell in vacuum demo). Speed ~340 m/s air, faster in liquids/solids.$cm$, sort_order = 3 where id = '8248f595-ae96-4b40-9522-9e52bbc24c19';
update public.flashcards set front = $cm$Echo problems$cm$, back = $cm$Distance = (v × t)/2 (there and back).$cm$, sort_order = 4 where id = '9b134c51-a5fb-4c5c-82db-3271d277d152';
update public.flashcards set front = $cm$Reflection$cm$, back = $cm$angle in = angle out; speed/frequency unchanged, direction changes.$cm$, sort_order = 5 where id = 'b1bcbf1c-0398-48b6-aa7e-8b15ee697681';
